export default JSON.parse("{\"workId\":\"xunzi\",\"chapter\":{\"id\":\"xunzi_ch-15\",\"workId\":\"xunzi\",\"order\":15,\"title\":\"議兵\",\"difficulty\":4,\"estimatedMinutes\":16,\"passageIds\":[\"xunzi_ch-15_p-1\",\"xunzi_ch-15_p-2\",\"xunzi_ch-15_p-3\",\"xunzi_ch-15_p-4\",\"xunzi_ch-15_p-5\",\"xunzi_ch-15_p-6\",\"xunzi_ch-15_p-7\",\"xunzi_ch-15_p-8\",\"xunzi_ch-15_p-9\",\"xunzi_ch-15_p-10\",\"xunzi_ch-15_p-11\",\"xunzi_ch-15_p-12\",\"xunzi_ch-15_p-13\",\"xunzi_ch-15_p-14\",\"xunzi_ch-15_p-15\",\"xunzi_ch-15_p-16\",\"xunzi_ch-15_p-17\",\"xunzi_ch-15_p-18\",\"xunzi_ch-15_p-19\",\"xunzi_ch-15_p-20\",\"xunzi_ch-15_p-21\",\"xunzi_ch-15_p-22\",\"xunzi_ch-15_p-23\",\"xunzi_ch-15_p-24\",\"xunzi_ch-15_p-25\",\"xunzi_ch-15_p-26\",\"xunzi_ch-15_p-27\"],\"tags\":[\"儒家\",\"性惡論\",\"禮樂\"]},\"passages\":[{\"id\":\"xunzi_ch-15_p-1\",\"chapterId\":\"xunzi_ch-15\",\"order\":1,\"canonicalText\":\"臨武君與孫卿子議兵於趙孝成王前，王曰：請問兵要？\",\"sentenceIds\":[\"xunzi_ch-15_p-1_s-1\"],\"sourceRefs\":[{\"label\":\"《荀子》—中國哲學書電子化計劃\",\"edition\":\"王先謙《荀子集解》本\",\"location\":\"https://ctext.org/xunzi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《荀子》—維基文庫\",\"edition\":\"楊倞注《荀子》四部叢刊本\",\"location\":\"https://zh.wikisource.org/zh-hant/荀子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"臨武君與孫卿子議兵於趙孝成王前，王說道：請問兵要？\",\"analysis\":\"【荀學篇旨與核心哲思】\\\\n本段選自先秦儒學集大成之作《荀子》〈議兵〉（第 1 節）。文本依據唐楊倞注與清王先謙《荀子集解》之權威學術體系，深刻闡發了荀子「化性起偽」、「隆禮重法」、「明分使羣」與「天行有常」之哲學主旨。開篇「臨武君與孫卿子議兵於趙孝成王前，王曰：請問兵要」提綱挈領，立意宏遠。\\\\n\\\\n【名物義理與章法論辯】\\\\n1. 概念範疇與論證推進：全段聚焦「臨武君與孫卿子議兵於趙孝成王前，王曰：請問兵要？」，荀子善用嚴密之邏輯推理、對比論證與生動譬喻，層層剖析人性自私與社會秩序之建構，論證禮義法度乃聖人積思慮、習偽故所生之社會規範。\\\\n2. 語言風格與先秦散文特色：文氣雄渾博大、句式整飭駢散結合，說理透闢犀利，既重道德禮義之教化，又重功用實效與制度規章。\\\\n\\\\n【經世致用與儒學集大成】\\\\n荀子整合先秦諸子學術精華，兼取法家之法治勢能與墨家之尚賢節用，將儒家仁義思想落實為具體的禮樂刑政與王霸之道，為後世大一統王朝之制度文明與經學思想奠定了堅實根基。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"xunzi_ch-15_p-2\",\"chapterId\":\"xunzi_ch-15\",\"order\":2,\"canonicalText\":\"臨武君對曰：上得天時，下得地利，觀敵之變動，後之發，先之至，此用兵之要術也。\",\"sentenceIds\":[\"xunzi_ch-15_p-2_s-1\"],\"sourceRefs\":[{\"label\":\"《荀子》—中國哲學書電子化計劃\",\"edition\":\"王先謙《荀子集解》本\",\"location\":\"https://ctext.org/xunzi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《荀子》—維基文庫\",\"edition\":\"楊倞注《荀子》四部叢刊本\",\"location\":\"https://zh.wikisource.org/zh-hant/荀子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"臨武君對說道：上得天時，下得地利，觀敵的變動，後的發，先的至，此用兵的要術啊。\",\"analysis\":\"【荀學篇旨與核心哲思】\\\\n本段選自先秦儒學集大成之作《荀子》〈議兵〉（第 2 節）。文本依據唐楊倞注與清王先謙《荀子集解》之權威學術體系，深刻闡發了荀子「化性起偽」、「隆禮重法」、「明分使羣」與「天行有常」之哲學主旨。開篇「臨武君對曰：上得天時，下得地利，觀敵之變動，後之發，先之至，此用兵之要術也」提綱挈領，立意宏遠。\\\\n\\\\n【名物義理與章法論辯】\\\\n1. 概念範疇與論證推進：全段聚焦「臨武君對曰：上得天時，下得地利，觀敵之變動，後之發，……」，荀子善用嚴密之邏輯推理、對比論證與生動譬喻，層層剖析人性自私與社會秩序之建構，論證禮義法度乃聖人積思慮、習偽故所生之社會規範。\\\\n2. 語言風格與先秦散文特色：文氣雄渾博大、句式整飭駢散結合，說理透闢犀利，既重道德禮義之教化，又重功用實效與制度規章。\\\\n\\\\n【經世致用與儒學集大成】\\\\n荀子整合先秦諸子學術精華，兼取法家之法治勢能與墨家之尚賢節用，將儒家仁義思想落實為具體的禮樂刑政與王霸之道，為後世大一統王朝之制度文明與經學思想奠定了堅實根基。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"xunzi_ch-15_p-3\",\"chapterId\":\"xunzi_ch-15\",\"order\":3,\"canonicalText\":\"孫卿子曰：不然！臣所聞古之道，凡用兵攻戰之本，在乎壹民。弓矢不調，則羿不能以中微；六馬不和，則造父不能以致遠；士民不親附，則湯武不能以必勝也。故善附民者，是乃善用兵者也。故兵要在乎善附民而已。\",\"sentenceIds\":[\"xunzi_ch-15_p-3_s-1\",\"xunzi_ch-15_p-3_s-2\",\"xunzi_ch-15_p-3_s-3\",\"xunzi_ch-15_p-3_s-4\",\"xunzi_ch-15_p-3_s-5\",\"xunzi_ch-15_p-3_s-6\",\"xunzi_ch-15_p-3_s-7\"],\"sourceRefs\":[{\"label\":\"《荀子》—中國哲學書電子化計劃\",\"edition\":\"王先謙《荀子集解》本\",\"location\":\"https://ctext.org/xunzi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《荀子》—維基文庫\",\"edition\":\"楊倞注《荀子》四部叢刊本\",\"location\":\"https://zh.wikisource.org/zh-hant/荀子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"孫卿子說道：不然！臣所聞古的道，凡用兵攻戰的本，在乎壹民。弓矢不調，則羿不能以中微；六馬不和，則造父不能以致遠；士民不親附，則湯武不能以必勝啊。所以善附民的人或事物，是乃善用兵的人或事物啊。所以兵要在乎善附民而且已。\",\"analysis\":\"【荀學篇旨與核心哲思】\\\\n本段選自先秦儒學集大成之作《荀子》〈議兵〉（第 3 節）。文本依據唐楊倞注與清王先謙《荀子集解》之權威學術體系，深刻闡發了荀子「化性起偽」、「隆禮重法」、「明分使羣」與「天行有常」之哲學主旨。開篇「孫卿子曰：不然」提綱挈領，立意宏遠。\\\\n\\\\n【名物義理與章法論辯】\\\\n1. 概念範疇與論證推進：全段聚焦「孫卿子曰：不然！臣所聞古之道，凡用兵攻戰之本，在乎壹……」，荀子善用嚴密之邏輯推理、對比論證與生動譬喻，層層剖析人性自私與社會秩序之建構，論證禮義法度乃聖人積思慮、習偽故所生之社會規範。\\\\n2. 語言風格與先秦散文特色：文氣雄渾博大、句式整飭駢散結合，說理透闢犀利，既重道德禮義之教化，又重功用實效與制度規章。\\\\n\\\\n【經世致用與儒學集大成】\\\\n荀子整合先秦諸子學術精華，兼取法家之法治勢能與墨家之尚賢節用，將儒家仁義思想落實為具體的禮樂刑政與王霸之道，為後世大一統王朝之制度文明與經學思想奠定了堅實根基。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"xunzi_ch-15_p-4\",\"chapterId\":\"xunzi_ch-15\",\"order\":4,\"canonicalText\":\"臨武君曰：不然。兵之所貴者埶利也，所行者變詐也。善用兵者，感忽悠闇，莫知其所從出。孫吳用之無敵於天下，豈必待附民哉！\",\"sentenceIds\":[\"xunzi_ch-15_p-4_s-1\",\"xunzi_ch-15_p-4_s-2\",\"xunzi_ch-15_p-4_s-3\",\"xunzi_ch-15_p-4_s-4\"],\"sourceRefs\":[{\"label\":\"《荀子》—中國哲學書電子化計劃\",\"edition\":\"王先謙《荀子集解》本\",\"location\":\"https://ctext.org/xunzi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《荀子》—維基文庫\",\"edition\":\"楊倞注《荀子》四部叢刊本\",\"location\":\"https://zh.wikisource.org/zh-hant/荀子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"臨武君說道：不然。兵的所貴的人或事物埶利啊，所行的人或事物變詐啊。善用兵的人或事物，感忽悠闇，莫知他的所從出。孫吳用的無敵於天下，豈必待附民哉！\",\"analysis\":\"【荀學篇旨與核心哲思】\\\\n本段選自先秦儒學集大成之作《荀子》〈議兵〉（第 4 節）。文本依據唐楊倞注與清王先謙《荀子集解》之權威學術體系，深刻闡發了荀子「化性起偽」、「隆禮重法」、「明分使羣」與「天行有常」之哲學主旨。開篇「臨武君曰：不然」提綱挈領，立意宏遠。\\\\n\\\\n【名物義理與章法論辯】\\\\n1. 概念範疇與論證推進：全段聚焦「臨武君曰：不然。兵之所貴者埶利也，所行者變詐也。善用……」，荀子善用嚴密之邏輯推理、對比論證與生動譬喻，層層剖析人性自私與社會秩序之建構，論證禮義法度乃聖人積思慮、習偽故所生之社會規範。\\\\n2. 語言風格與先秦散文特色：文氣雄渾博大、句式整飭駢散結合，說理透闢犀利，既重道德禮義之教化，又重功用實效與制度規章。\\\\n\\\\n【經世致用與儒學集大成】\\\\n荀子整合先秦諸子學術精華，兼取法家之法治勢能與墨家之尚賢節用，將儒家仁義思想落實為具體的禮樂刑政與王霸之道，為後世大一統王朝之制度文明與經學思想奠定了堅實根基。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"xunzi_ch-15_p-5\",\"chapterId\":\"xunzi_ch-15\",\"order\":5,\"canonicalText\":\"孫卿子曰：不然。臣之所道，仁者之兵，王者之志也。君之所貴，權謀埶利也；所行，攻奪變詐也；諸侯之事也。仁人之兵，不可詐也；彼可詐者，怠慢者也，路亶者也，君臣上下之間，渙然有離德者也。故以桀詐桀，猶巧拙有幸焉。以桀詐堯，譬之：若以卵投石，以指撓沸；若赴水火，入焉焦沒耳。故仁人上下，百將一心，三軍同力；臣之於君也，下之於上也，若子之事父，弟之事兄，若手臂之扞頭目而覆胸腹也，詐而襲之，與先驚而後擊之，一也。且仁人之用十里之國，則將有百里之聽；用百里之國，則將有千里之聽；用千里之國，則將有四海之聽，必將聰明警戒和傳而一。故仁人之兵，聚則成卒，散則成列，延則若莫邪之長刃，嬰之者斷；兌則若莫邪之利鋒，當之者潰，圜居而方止，則若盤石然，觸之者角摧，案角鹿埵隴種東籠而退耳。且夫暴國之君，將誰與至哉？彼其所與至者，必其民也，而其民之親我歡若父母，其好我芬若椒蘭，彼反顧其上，則若灼黥，若讎仇；人之情，雖桀蹠，豈又肯為其所惡，賊其所好者哉！是猶使人之子孫自賊其父母也，彼必將來告之，夫又何可詐也！故仁人用國日明，諸侯先順者安，後順者危，慮敵之者削，反之者亡。《詩》曰：「武王載發，有虔秉鉞；如火烈烈，則莫我敢遏。」此之謂也。\",\"sentenceIds\":[\"xunzi_ch-15_p-5_s-1\",\"xunzi_ch-15_p-5_s-2\",\"xunzi_ch-15_p-5_s-3\",\"xunzi_ch-15_p-5_s-4\",\"xunzi_ch-15_p-5_s-5\",\"xunzi_ch-15_p-5_s-6\",\"xunzi_ch-15_p-5_s-7\",\"xunzi_ch-15_p-5_s-8\",\"xunzi_ch-15_p-5_s-9\",\"xunzi_ch-15_p-5_s-10\",\"xunzi_ch-15_p-5_s-11\",\"xunzi_ch-15_p-5_s-12\",\"xunzi_ch-15_p-5_s-13\",\"xunzi_ch-15_p-5_s-14\",\"xunzi_ch-15_p-5_s-15\",\"xunzi_ch-15_p-5_s-16\",\"xunzi_ch-15_p-5_s-17\",\"xunzi_ch-15_p-5_s-18\",\"xunzi_ch-15_p-5_s-19\",\"xunzi_ch-15_p-5_s-20\",\"xunzi_ch-15_p-5_s-21\",\"xunzi_ch-15_p-5_s-22\",\"xunzi_ch-15_p-5_s-23\",\"xunzi_ch-15_p-5_s-24\",\"xunzi_ch-15_p-5_s-25\"],\"sourceRefs\":[{\"label\":\"《荀子》—中國哲學書電子化計劃\",\"edition\":\"王先謙《荀子集解》本\",\"location\":\"https://ctext.org/xunzi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《荀子》—維基文庫\",\"edition\":\"楊倞注《荀子》四部叢刊本\",\"location\":\"https://zh.wikisource.org/zh-hant/荀子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"孫卿子說道：不然。臣的所道，仁愛慈悲之德的人或事物的兵，王的人或事物的志啊。君的所貴，權謀埶利啊；所行，攻奪變詐啊；諸侯的事啊。仁愛慈悲之德人的兵，不可詐啊；彼可詐的人或事物，怠慢的人或事物啊，路亶的人或事物啊，君臣上下的間，渙然有離品德修養的人或事物啊。所以以桀詐桀，猶巧拙有幸焉。以桀詐堯，譬的：若以卵投石，以指撓沸；若赴水火，入焉焦沒耳。所以仁愛慈悲之德人上下，百將一心，三軍同力；臣的於君啊，下的於上啊，若子的事父，弟的事兄，若手臂的扞頭目而且覆胸腹啊，詐而且襲的，與先驚而且後擊的，一啊。且仁愛慈悲之德人的用十里的國，則將有百里的聽；用百里的國，則將有千里的聽；用千里的國，則將有四海的聽，必將聰明警戒和傳而且一。所以仁愛慈悲之德人的兵，聚則成卒，散則成列，延則若莫邪的長刃，嬰的的人或事物斷；兌則若莫邪的利鋒，當的的人或事物潰，圜居而且方止，則若盤石然，觸的的人或事物角摧，案角鹿埵隴種東籠而且退耳。再的人或事物況且暴國的君，將誰與至哉？彼他的所與至的人或事物，必他的民啊，而且他的民的親我歡若父母，他的好我芬若椒蘭，彼反顧他的上，則若灼黥，若讎仇；人的情，雖桀蹠，豈又肯為他的所惡，賊他的所好的人或事物哉！是猶使人的子孫自賊他的父母啊，彼必將來告的，夫又何可詐啊！所以仁愛慈悲之德人用國日明，諸侯先順的人或事物安，後順的人或事物危，慮敵的的人或事物削，反的的人或事物亡。《詩》說道：武王載發，有虔秉鉞；如火烈烈，則莫我敢遏。此的謂啊。\",\"analysis\":\"【荀學篇旨與核心哲思】\\\\n本段選自先秦儒學集大成之作《荀子》〈議兵〉（第 5 節）。文本依據唐楊倞注與清王先謙《荀子集解》之權威學術體系，深刻闡發了荀子「化性起偽」、「隆禮重法」、「明分使羣」與「天行有常」之哲學主旨。開篇「孫卿子曰：不然」提綱挈領，立意宏遠。\\\\n\\\\n【名物義理與章法論辯】\\\\n1. 概念範疇與論證推進：全段聚焦「孫卿子曰：不然。臣之所道，仁者之兵，王者之志也。君之……」，荀子善用嚴密之邏輯推理、對比論證與生動譬喻，層層剖析人性自私與社會秩序之建構，論證禮義法度乃聖人積思慮、習偽故所生之社會規範。\\\\n2. 語言風格與先秦散文特色：文氣雄渾博大、句式整飭駢散結合，說理透闢犀利，既重道德禮義之教化，又重功用實效與制度規章。\\\\n\\\\n【經世致用與儒學集大成】\\\\n荀子整合先秦諸子學術精華，兼取法家之法治勢能與墨家之尚賢節用，將儒家仁義思想落實為具體的禮樂刑政與王霸之道，為後世大一統王朝之制度文明與經學思想奠定了堅實根基。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"xunzi_ch-15_p-6\",\"chapterId\":\"xunzi_ch-15\",\"order\":6,\"canonicalText\":\"孝成王、臨武君曰：善！請問王者之兵，設何道何行而可？\",\"sentenceIds\":[\"xunzi_ch-15_p-6_s-1\",\"xunzi_ch-15_p-6_s-2\"],\"sourceRefs\":[{\"label\":\"《荀子》—中國哲學書電子化計劃\",\"edition\":\"王先謙《荀子集解》本\",\"location\":\"https://ctext.org/xunzi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《荀子》—維基文庫\",\"edition\":\"楊倞注《荀子》四部叢刊本\",\"location\":\"https://zh.wikisource.org/zh-hant/荀子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"孝成王、臨武君說道：善！請問王的人或事物的兵，設何道何行而且可？\",\"analysis\":\"【荀學篇旨與核心哲思】\\\\n本段選自先秦儒學集大成之作《荀子》〈議兵〉（第 6 節）。文本依據唐楊倞注與清王先謙《荀子集解》之權威學術體系，深刻闡發了荀子「化性起偽」、「隆禮重法」、「明分使羣」與「天行有常」之哲學主旨。開篇「孝成王、臨武君曰：善」提綱挈領，立意宏遠。\\\\n\\\\n【名物義理與章法論辯】\\\\n1. 概念範疇與論證推進：全段聚焦「孝成王、臨武君曰：善！請問王者之兵，設何道何行而可？」，荀子善用嚴密之邏輯推理、對比論證與生動譬喻，層層剖析人性自私與社會秩序之建構，論證禮義法度乃聖人積思慮、習偽故所生之社會規範。\\\\n2. 語言風格與先秦散文特色：文氣雄渾博大、句式整飭駢散結合，說理透闢犀利，既重道德禮義之教化，又重功用實效與制度規章。\\\\n\\\\n【經世致用與儒學集大成】\\\\n荀子整合先秦諸子學術精華，兼取法家之法治勢能與墨家之尚賢節用，將儒家仁義思想落實為具體的禮樂刑政與王霸之道，為後世大一統王朝之制度文明與經學思想奠定了堅實根基。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"xunzi_ch-15_p-7\",\"chapterId\":\"xunzi_ch-15\",\"order\":7,\"canonicalText\":\"孫卿子曰：凡在大王，將率末事也。臣請遂道王者諸侯強弱存亡之效，安危之埶：君賢者其國治，君不能者其國亂；隆禮貴義者其國治，簡禮賤義者其國亂；治者強，亂者弱，是強弱之本也。上足卬則下可用也，上不卬則下不可用也；下可用則強，下不可用則弱，是強弱之常也。隆禮效功，上也；重祿貴節，次也；上功賤節，下也，是強弱之凡也。好士者強，不好士者弱；愛民者強，不愛民者弱；政令信者強，政令不信者弱；民齊者強，民不齊者弱；賞重者強，賞輕者弱；刑威者強，刑侮者弱；械用兵革攻完便利者強，械用兵革窳楛不便利者弱。重用兵者強，輕用兵者弱；權出一者強，權出二者弱，是強弱之常也。\",\"sentenceIds\":[\"xunzi_ch-15_p-7_s-1\",\"xunzi_ch-15_p-7_s-2\",\"xunzi_ch-15_p-7_s-3\",\"xunzi_ch-15_p-7_s-4\",\"xunzi_ch-15_p-7_s-5\",\"xunzi_ch-15_p-7_s-6\",\"xunzi_ch-15_p-7_s-7\",\"xunzi_ch-15_p-7_s-8\",\"xunzi_ch-15_p-7_s-9\",\"xunzi_ch-15_p-7_s-10\",\"xunzi_ch-15_p-7_s-11\",\"xunzi_ch-15_p-7_s-12\",\"xunzi_ch-15_p-7_s-13\",\"xunzi_ch-15_p-7_s-14\",\"xunzi_ch-15_p-7_s-15\",\"xunzi_ch-15_p-7_s-16\",\"xunzi_ch-15_p-7_s-17\",\"xunzi_ch-15_p-7_s-18\"],\"sourceRefs\":[{\"label\":\"《荀子》—中國哲學書電子化計劃\",\"edition\":\"王先謙《荀子集解》本\",\"location\":\"https://ctext.org/xunzi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《荀子》—維基文庫\",\"edition\":\"楊倞注《荀子》四部叢刊本\",\"location\":\"https://zh.wikisource.org/zh-hant/荀子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"孫卿子說道：凡在大王，將率末事啊。臣請遂道王的人或事物諸侯強弱存亡的效，安危的埶：君賢的人或事物他的國治，君不能的人或事物他的國亂；隆禮正義道義道品德修養規程貴正義道義的人或事物他的國治，簡禮正義道義道品德修養規程賤正義道義的人或事物他的國亂；治的人或事物強，亂的人或事物弱，是強弱的本啊。上足卬則下可用啊，上不卬則下不可用啊；下可用則強，下不可用則弱，是強弱的常啊。隆禮正義道義道品德修養規程效功，上啊；重祿貴節，次啊；上功賤節，下啊，是強弱的凡啊。好士的人或事物強，不好士的人或事物弱；愛民的人或事物強，不愛民的人或事物弱；政令信的人或事物強，政令不信的人或事物弱；民齊的人或事物強，民不齊的人或事物弱；賞重的人或事物強，賞輕的人或事物弱；刑威的人或事物強，刑侮的人或事物弱；械用兵革攻完便利的人或事物強，械用兵革窳楛不便利的人或事物弱。重用兵的人或事物強，輕用兵的人或事物弱；權出一的人或事物強，權出二的人或事物弱，是強弱的常啊。\",\"analysis\":\"【荀學篇旨與核心哲思】\\\\n本段選自先秦儒學集大成之作《荀子》〈議兵〉（第 7 節）。文本依據唐楊倞注與清王先謙《荀子集解》之權威學術體系，深刻闡發了荀子「化性起偽」、「隆禮重法」、「明分使羣」與「天行有常」之哲學主旨。開篇「孫卿子曰：凡在大王，將率末事也」提綱挈領，立意宏遠。\\\\n\\\\n【名物義理與章法論辯】\\\\n1. 概念範疇與論證推進：全段聚焦「孫卿子曰：凡在大王，將率末事也。臣請遂道王者諸侯強弱……」，荀子善用嚴密之邏輯推理、對比論證與生動譬喻，層層剖析人性自私與社會秩序之建構，論證禮義法度乃聖人積思慮、習偽故所生之社會規範。\\\\n2. 語言風格與先秦散文特色：文氣雄渾博大、句式整飭駢散結合，說理透闢犀利，既重道德禮義之教化，又重功用實效與制度規章。\\\\n\\\\n【經世致用與儒學集大成】\\\\n荀子整合先秦諸子學術精華，兼取法家之法治勢能與墨家之尚賢節用，將儒家仁義思想落實為具體的禮樂刑政與王霸之道，為後世大一統王朝之制度文明與經學思想奠定了堅實根基。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"xunzi_ch-15_p-8\",\"chapterId\":\"xunzi_ch-15\",\"order\":8,\"canonicalText\":\"齊人隆技擊，其技也，得一首者，則賜贖錙金，無本賞矣。是事小敵毳，則偷可用也，事大敵堅，則渙然離耳。若飛鳥然，傾側反覆無日，是亡國之兵也，兵莫弱是矣。是其去賃市傭而戰之幾矣。\",\"sentenceIds\":[\"xunzi_ch-15_p-8_s-1\",\"xunzi_ch-15_p-8_s-2\",\"xunzi_ch-15_p-8_s-3\",\"xunzi_ch-15_p-8_s-4\"],\"sourceRefs\":[{\"label\":\"《荀子》—中國哲學書電子化計劃\",\"edition\":\"王先謙《荀子集解》本\",\"location\":\"https://ctext.org/xunzi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《荀子》—維基文庫\",\"edition\":\"楊倞注《荀子》四部叢刊本\",\"location\":\"https://zh.wikisource.org/zh-hant/荀子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"齊人隆技擊，他的技啊，得一首的人或事物，則賜贖錙金，無本賞矣。是事小敵毳，則偷可用啊，事大敵堅，則渙然離耳。若飛鳥然，傾側反覆無日，是亡國的兵啊，兵莫弱是矣。是他的去賃市傭而且戰的幾矣。\",\"analysis\":\"【荀學篇旨與核心哲思】\\\\n本段選自先秦儒學集大成之作《荀子》〈議兵〉（第 8 節）。文本依據唐楊倞注與清王先謙《荀子集解》之權威學術體系，深刻闡發了荀子「化性起偽」、「隆禮重法」、「明分使羣」與「天行有常」之哲學主旨。開篇「齊人隆技擊，其技也，得一首者，則賜贖錙金，無本賞矣」提綱挈領，立意宏遠。\\\\n\\\\n【名物義理與章法論辯】\\\\n1. 概念範疇與論證推進：全段聚焦「齊人隆技擊，其技也，得一首者，則賜贖錙金，無本賞矣。……」，荀子善用嚴密之邏輯推理、對比論證與生動譬喻，層層剖析人性自私與社會秩序之建構，論證禮義法度乃聖人積思慮、習偽故所生之社會規範。\\\\n2. 語言風格與先秦散文特色：文氣雄渾博大、句式整飭駢散結合，說理透闢犀利，既重道德禮義之教化，又重功用實效與制度規章。\\\\n\\\\n【經世致用與儒學集大成】\\\\n荀子整合先秦諸子學術精華，兼取法家之法治勢能與墨家之尚賢節用，將儒家仁義思想落實為具體的禮樂刑政與王霸之道，為後世大一統王朝之制度文明與經學思想奠定了堅實根基。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"xunzi_ch-15_p-9\",\"chapterId\":\"xunzi_ch-15\",\"order\":9,\"canonicalText\":\"魏氏之武卒，以度取之，衣三屬之甲，操十二石之弩，負服矢五十個，置戈其上，冠冑帶劍，贏三日之糧，日中而趨百里，中試則復其戶，利其田宅，是數年而衰，而未可奪也，改造則不易周也，是故地雖大，其稅必寡，是危國之兵也。\",\"sentenceIds\":[\"xunzi_ch-15_p-9_s-1\"],\"sourceRefs\":[{\"label\":\"《荀子》—中國哲學書電子化計劃\",\"edition\":\"王先謙《荀子集解》本\",\"location\":\"https://ctext.org/xunzi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《荀子》—維基文庫\",\"edition\":\"楊倞注《荀子》四部叢刊本\",\"location\":\"https://zh.wikisource.org/zh-hant/荀子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"魏氏的武卒，以度取的，衣三屬的甲，操十二石的弩，負服矢五十個，置戈他的上，冠冑帶劍，贏三日的糧，日中而且趨百里，中試則復他的戶，利他的田宅，是數年而且衰，而且未可奪啊，改造則不易周啊，正因為如此地雖大，他的稅必寡，是危國的兵啊。\",\"analysis\":\"【荀學篇旨與核心哲思】\\\\n本段選自先秦儒學集大成之作《荀子》〈議兵〉（第 9 節）。文本依據唐楊倞注與清王先謙《荀子集解》之權威學術體系，深刻闡發了荀子「化性起偽」、「隆禮重法」、「明分使羣」與「天行有常」之哲學主旨。開篇「魏氏之武卒，以度取之，衣三屬之甲，操十二石之弩，負服矢五十個，置戈其上，冠冑帶劍，贏三日之糧，日中而趨百里，中試則復其戶，利其田宅，是數年而衰，而未可奪也，改造則不易周也，是故地雖大，其稅必寡，是危國之兵也」提綱挈領，立意宏遠。\\\\n\\\\n【名物義理與章法論辯】\\\\n1. 概念範疇與論證推進：全段聚焦「魏氏之武卒，以度取之，衣三屬之甲，操十二石之弩，負服……」，荀子善用嚴密之邏輯推理、對比論證與生動譬喻，層層剖析人性自私與社會秩序之建構，論證禮義法度乃聖人積思慮、習偽故所生之社會規範。\\\\n2. 語言風格與先秦散文特色：文氣雄渾博大、句式整飭駢散結合，說理透闢犀利，既重道德禮義之教化，又重功用實效與制度規章。\\\\n\\\\n【經世致用與儒學集大成】\\\\n荀子整合先秦諸子學術精華，兼取法家之法治勢能與墨家之尚賢節用，將儒家仁義思想落實為具體的禮樂刑政與王霸之道，為後世大一統王朝之制度文明與經學思想奠定了堅實根基。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"xunzi_ch-15_p-10\",\"chapterId\":\"xunzi_ch-15\",\"order\":10,\"canonicalText\":\"秦人其生民郟阨，其使民也酷烈，劫之以埶，隱之以阨，忸之以慶賞，酋之以刑罰，使天下之民，所以要利於上者，非鬥無由也。阨而用之，得而後功之，功賞相長也，五甲首而隸五家，是最為眾強長久，多地以正，故四世有勝，非幸也，數也。\",\"sentenceIds\":[\"xunzi_ch-15_p-10_s-1\",\"xunzi_ch-15_p-10_s-2\"],\"sourceRefs\":[{\"label\":\"《荀子》—中國哲學書電子化計劃\",\"edition\":\"王先謙《荀子集解》本\",\"location\":\"https://ctext.org/xunzi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《荀子》—維基文庫\",\"edition\":\"楊倞注《荀子》四部叢刊本\",\"location\":\"https://zh.wikisource.org/zh-hant/荀子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"秦人他的生民郟阨，他的使民啊酷烈，劫的以埶，隱的以阨，忸的以慶賞，酋的以刑罰，使天下的民，所以要利於上的人或事物，絕不是鬥無由啊。阨而且用的，得而且後功的，功賞相長啊，五甲首而且隸五家，是最為眾強長久，多地以正，所以四世有勝，絕不是幸啊，數啊。\",\"analysis\":\"【荀學篇旨與核心哲思】\\\\n本段選自先秦儒學集大成之作《荀子》〈議兵〉（第 10 節）。文本依據唐楊倞注與清王先謙《荀子集解》之權威學術體系，深刻闡發了荀子「化性起偽」、「隆禮重法」、「明分使羣」與「天行有常」之哲學主旨。開篇「秦人其生民郟阨，其使民也酷烈，劫之以埶，隱之以阨，忸之以慶賞，酋之以刑罰，使天下之民，所以要利於上者，非鬥無由也」提綱挈領，立意宏遠。\\\\n\\\\n【名物義理與章法論辯】\\\\n1. 概念範疇與論證推進：全段聚焦「秦人其生民郟阨，其使民也酷烈，劫之以埶，隱之以阨，忸……」，荀子善用嚴密之邏輯推理、對比論證與生動譬喻，層層剖析人性自私與社會秩序之建構，論證禮義法度乃聖人積思慮、習偽故所生之社會規範。\\\\n2. 語言風格與先秦散文特色：文氣雄渾博大、句式整飭駢散結合，說理透闢犀利，既重道德禮義之教化，又重功用實效與制度規章。\\\\n\\\\n【經世致用與儒學集大成】\\\\n荀子整合先秦諸子學術精華，兼取法家之法治勢能與墨家之尚賢節用，將儒家仁義思想落實為具體的禮樂刑政與王霸之道，為後世大一統王朝之制度文明與經學思想奠定了堅實根基。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"xunzi_ch-15_p-11\",\"chapterId\":\"xunzi_ch-15\",\"order\":11,\"canonicalText\":\"故齊之技擊，不可以遇魏氏之武卒；魏氏之武卒，不可以遇秦之銳士；秦之銳士，不可以當桓文之節制；桓文之節制，不可以敵湯武之仁義；有遇之者，若以焦熬投石焉。兼是數國者，皆幹賞蹈利之兵也，傭徒鬻賣之道也，未有貴上安制綦節之理也。諸侯有能微妙之以節，則作而兼殆之耳。故招近募選，隆埶詐，尚功利，是漸之也；禮義教化，是齊之也。故以詐遇詐，猶有巧拙焉；以詐遇齊，闢之猶以錐刀墮太山也，非天下之愚人莫敢試。故王者之兵不試。湯武之誅桀紂也，拱挹指麾，而強暴之國莫不趨使，誅桀紂若誅獨夫。故泰誓曰：「獨夫紂。」此之謂也。故兵大齊則制天下，小齊則治鄰敵。若夫招近募選，隆埶詐，尚功利之兵，則勝不勝無常，代翕代張，代存代亡，相為雌雄耳矣。夫是之謂盜兵，君子不由也。\",\"sentenceIds\":[\"xunzi_ch-15_p-11_s-1\",\"xunzi_ch-15_p-11_s-2\",\"xunzi_ch-15_p-11_s-3\",\"xunzi_ch-15_p-11_s-4\",\"xunzi_ch-15_p-11_s-5\",\"xunzi_ch-15_p-11_s-6\",\"xunzi_ch-15_p-11_s-7\",\"xunzi_ch-15_p-11_s-8\",\"xunzi_ch-15_p-11_s-9\",\"xunzi_ch-15_p-11_s-10\",\"xunzi_ch-15_p-11_s-11\",\"xunzi_ch-15_p-11_s-12\",\"xunzi_ch-15_p-11_s-13\",\"xunzi_ch-15_p-11_s-14\",\"xunzi_ch-15_p-11_s-15\",\"xunzi_ch-15_p-11_s-16\",\"xunzi_ch-15_p-11_s-17\",\"xunzi_ch-15_p-11_s-18\"],\"sourceRefs\":[{\"label\":\"《荀子》—中國哲學書電子化計劃\",\"edition\":\"王先謙《荀子集解》本\",\"location\":\"https://ctext.org/xunzi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《荀子》—維基文庫\",\"edition\":\"楊倞注《荀子》四部叢刊本\",\"location\":\"https://zh.wikisource.org/zh-hant/荀子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"所以齊的技擊，不可以遇魏氏的武卒；魏氏的武卒，不可以遇秦的銳士；秦的銳士，不可以當桓文的節制；桓文的節制，不可以敵湯武的仁愛慈悲之德正義道義；有遇的的人或事物，若以焦熬投石焉。兼是數國的人或事物，皆幹賞蹈利的兵啊，傭徒鬻賣的道啊，未有貴上安制綦節的理啊。諸侯有能微妙的以節，則作而且兼殆的耳。所以招近募選，隆埶詐，尚功利，是漸的啊；禮正義道義道品德修養規程正義道義教化，是齊的啊。所以以詐遇詐，猶有巧拙焉；以詐遇齊，闢的猶以錐刀墮太山啊，絕不是天下的愚人莫敢試。所以王的人或事物的兵不試。湯武的誅桀紂啊，拱挹指麾，而且強暴的國莫不趨使，誅桀紂若誅獨夫。所以泰誓說道：獨夫紂。此的謂啊。所以兵大齊則制天下，小齊則治鄰敵。至於談到那招近募選，隆埶詐，尚功利的兵，則勝不勝無常，代翕代張，代存代亡，相為雌雄耳矣。這就是儒家所稱的盜兵，君子不由啊。\",\"analysis\":\"【荀學篇旨與核心哲思】\\\\n本段選自先秦儒學集大成之作《荀子》〈議兵〉（第 11 節）。文本依據唐楊倞注與清王先謙《荀子集解》之權威學術體系，深刻闡發了荀子「化性起偽」、「隆禮重法」、「明分使羣」與「天行有常」之哲學主旨。開篇「故齊之技擊，不可以遇魏氏之武卒」提綱挈領，立意宏遠。\\\\n\\\\n【名物義理與章法論辯】\\\\n1. 概念範疇與論證推進：全段聚焦「故齊之技擊，不可以遇魏氏之武卒；魏氏之武卒，不可以遇……」，荀子善用嚴密之邏輯推理、對比論證與生動譬喻，層層剖析人性自私與社會秩序之建構，論證禮義法度乃聖人積思慮、習偽故所生之社會規範。\\\\n2. 語言風格與先秦散文特色：文氣雄渾博大、句式整飭駢散結合，說理透闢犀利，既重道德禮義之教化，又重功用實效與制度規章。\\\\n\\\\n【經世致用與儒學集大成】\\\\n荀子整合先秦諸子學術精華，兼取法家之法治勢能與墨家之尚賢節用，將儒家仁義思想落實為具體的禮樂刑政與王霸之道，為後世大一統王朝之制度文明與經學思想奠定了堅實根基。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"xunzi_ch-15_p-12\",\"chapterId\":\"xunzi_ch-15\",\"order\":12,\"canonicalText\":\"故齊之田單，楚之莊蹻，秦之衛鞅，燕之繆蟣，是皆世俗所謂善用兵者也，是其巧拙強弱，則未有以相君也。若其道一也，未及和齊也；掎契司詐，權謀傾覆，未免盜兵也。齊桓、晉文、楚莊、吳闔閭、越勾踐是皆和齊之兵也，可謂入其域矣，然而未有本統也，故可以霸而不可以王；是強弱之效也。\",\"sentenceIds\":[\"xunzi_ch-15_p-12_s-1\",\"xunzi_ch-15_p-12_s-2\",\"xunzi_ch-15_p-12_s-3\",\"xunzi_ch-15_p-12_s-4\",\"xunzi_ch-15_p-12_s-5\"],\"sourceRefs\":[{\"label\":\"《荀子》—中國哲學書電子化計劃\",\"edition\":\"王先謙《荀子集解》本\",\"location\":\"https://ctext.org/xunzi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《荀子》—維基文庫\",\"edition\":\"楊倞注《荀子》四部叢刊本\",\"location\":\"https://zh.wikisource.org/zh-hant/荀子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"所以齊的田單，楚的莊蹻，秦的衛鞅，燕的繆蟣，是皆世俗所謂善用兵的人或事物啊，是他的巧拙強弱，則未有以相君啊。若他的道一啊，未及和齊啊；掎契司詐，權謀傾覆，未免盜兵啊。齊桓、晉文、楚莊、吳闔閭、越勾踐是皆和齊的兵啊，可謂入他的域矣，然而且未有本統啊，所以可以霸而且不可以王；是強弱的效啊。\",\"analysis\":\"【荀學篇旨與核心哲思】\\\\n本段選自先秦儒學集大成之作《荀子》〈議兵〉（第 12 節）。文本依據唐楊倞注與清王先謙《荀子集解》之權威學術體系，深刻闡發了荀子「化性起偽」、「隆禮重法」、「明分使羣」與「天行有常」之哲學主旨。開篇「故齊之田單，楚之莊蹻，秦之衛鞅，燕之繆蟣，是皆世俗所謂善用兵者也，是其巧拙強弱，則未有以相君也」提綱挈領，立意宏遠。\\\\n\\\\n【名物義理與章法論辯】\\\\n1. 概念範疇與論證推進：全段聚焦「故齊之田單，楚之莊蹻，秦之衛鞅，燕之繆蟣，是皆世俗所……」，荀子善用嚴密之邏輯推理、對比論證與生動譬喻，層層剖析人性自私與社會秩序之建構，論證禮義法度乃聖人積思慮、習偽故所生之社會規範。\\\\n2. 語言風格與先秦散文特色：文氣雄渾博大、句式整飭駢散結合，說理透闢犀利，既重道德禮義之教化，又重功用實效與制度規章。\\\\n\\\\n【經世致用與儒學集大成】\\\\n荀子整合先秦諸子學術精華，兼取法家之法治勢能與墨家之尚賢節用，將儒家仁義思想落實為具體的禮樂刑政與王霸之道，為後世大一統王朝之制度文明與經學思想奠定了堅實根基。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"xunzi_ch-15_p-13\",\"chapterId\":\"xunzi_ch-15\",\"order\":13,\"canonicalText\":\"孝成王、臨武君曰善！請問為將？\",\"sentenceIds\":[\"xunzi_ch-15_p-13_s-1\",\"xunzi_ch-15_p-13_s-2\"],\"sourceRefs\":[{\"label\":\"《荀子》—中國哲學書電子化計劃\",\"edition\":\"王先謙《荀子集解》本\",\"location\":\"https://ctext.org/xunzi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《荀子》—維基文庫\",\"edition\":\"楊倞注《荀子》四部叢刊本\",\"location\":\"https://zh.wikisource.org/zh-hant/荀子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"孝成王、臨武君說道：善！請問為將？\",\"analysis\":\"【荀學篇旨與核心哲思】\\\\n本段選自先秦儒學集大成之作《荀子》〈議兵〉（第 13 節）。文本依據唐楊倞注與清王先謙《荀子集解》之權威學術體系，深刻闡發了荀子「化性起偽」、「隆禮重法」、「明分使羣」與「天行有常」之哲學主旨。開篇「孝成王、臨武君曰善」提綱挈領，立意宏遠。\\\\n\\\\n【名物義理與章法論辯】\\\\n1. 概念範疇與論證推進：全段聚焦「孝成王、臨武君曰善！請問為將？」，荀子善用嚴密之邏輯推理、對比論證與生動譬喻，層層剖析人性自私與社會秩序之建構，論證禮義法度乃聖人積思慮、習偽故所生之社會規範。\\\\n2. 語言風格與先秦散文特色：文氣雄渾博大、句式整飭駢散結合，說理透闢犀利，既重道德禮義之教化，又重功用實效與制度規章。\\\\n\\\\n【經世致用與儒學集大成】\\\\n荀子整合先秦諸子學術精華，兼取法家之法治勢能與墨家之尚賢節用，將儒家仁義思想落實為具體的禮樂刑政與王霸之道，為後世大一統王朝之制度文明與經學思想奠定了堅實根基。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"xunzi_ch-15_p-14\",\"chapterId\":\"xunzi_ch-15\",\"order\":14,\"canonicalText\":\"孫卿子曰：知莫大乎棄疑，行莫大乎無過，事莫大乎無悔，事至無悔而止矣，成不可必也。故制號政令欲嚴以威，慶賞刑罰欲必以信，處舍收藏欲周以固，徙舉進退欲安以重，欲疾以速；窺敵觀變欲潛以深，欲伍以參；遇敵決戰必道吾所明，無道吾所疑：夫是之謂六術。無欲將而惡廢，無急勝而忘敗，無威內而輕外，無見利而不顧其害，凡慮事欲孰而用財欲泰：夫是之謂五權。所以不受命於主有三：可殺而不可使處不完，可殺而不可使擊不勝，可殺而不可使欺百姓：夫是之謂三至。凡受命於主而行三軍，三軍既定，百官得序，羣物皆正，則主不能喜，敵不能怒：夫是之謂至臣。慮必先事，而申之以敬，慎終如始，終始如一：夫是之謂大吉。凡百事之成也，必在敬之；其敗也，必在慢之。故敬勝怠則吉，怠勝敬則滅；計勝欲則從，欲勝計則兇。戰如守，行如戰，有功如幸，敬謀無壙，敬事無壙，敬吏無壙，敬眾無壙，敬敵無壙：夫是之謂五無壙。謹行此六術、五權、三至，而處之以恭敬無壙，夫是之謂天下之將，則通於神明矣。\",\"sentenceIds\":[\"xunzi_ch-15_p-14_s-1\",\"xunzi_ch-15_p-14_s-2\",\"xunzi_ch-15_p-14_s-3\",\"xunzi_ch-15_p-14_s-4\",\"xunzi_ch-15_p-14_s-5\",\"xunzi_ch-15_p-14_s-6\",\"xunzi_ch-15_p-14_s-7\",\"xunzi_ch-15_p-14_s-8\",\"xunzi_ch-15_p-14_s-9\",\"xunzi_ch-15_p-14_s-10\",\"xunzi_ch-15_p-14_s-11\",\"xunzi_ch-15_p-14_s-12\",\"xunzi_ch-15_p-14_s-13\",\"xunzi_ch-15_p-14_s-14\"],\"sourceRefs\":[{\"label\":\"《荀子》—中國哲學書電子化計劃\",\"edition\":\"王先謙《荀子集解》本\",\"location\":\"https://ctext.org/xunzi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《荀子》—維基文庫\",\"edition\":\"楊倞注《荀子》四部叢刊本\",\"location\":\"https://zh.wikisource.org/zh-hant/荀子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"孫卿子說道：知莫大乎棄疑，行莫大乎無過，事莫大乎無悔，事至無悔而且止矣，成不可必啊。所以制號政令欲嚴以威，慶賞刑罰欲必以信，處舍收藏欲周以固，徙舉進退欲安以重，欲疾以速；窺敵觀變欲潛以深，欲伍以參；遇敵決戰必道吾所明，無道吾所疑：這就是儒家所稱的六術。無欲將而且惡廢，無急勝而且忘敗，無威內而且輕外，無見利而且不顧他的害，凡慮事欲孰而且用財欲泰：這就是儒家所稱的五權。所以不受命於主有三：可殺而且不可使處不完，可殺而且不可使擊不勝，可殺而且不可使欺百姓：這就是儒家所稱的三至。凡受命於主而且行三軍，三軍既定，百官得序，羣物皆正，則主不能喜，敵不能怒：這就是儒家所稱的至臣。慮必先事，而且申的以敬，慎終如始，終始如一：這就是儒家所稱的大吉。凡百事的成啊，必在敬的；他的敗啊，必在慢的。所以敬勝怠則吉，怠勝敬則滅；計勝欲則從，欲勝計則兇。戰如守，行如戰，有功如幸，敬謀無壙，敬事無壙，敬吏無壙，敬眾無壙，敬敵無壙：這就是儒家所稱的五無壙。謹行此六術、五權、三至，而且處的以恭敬無壙，這就是儒家所稱的天下的將，則通於神明矣。\",\"analysis\":\"【荀學篇旨與核心哲思】\\\\n本段選自先秦儒學集大成之作《荀子》〈議兵〉（第 14 節）。文本依據唐楊倞注與清王先謙《荀子集解》之權威學術體系，深刻闡發了荀子「化性起偽」、「隆禮重法」、「明分使羣」與「天行有常」之哲學主旨。開篇「孫卿子曰：知莫大乎棄疑，行莫大乎無過，事莫大乎無悔，事至無悔而止矣，成不可必也」提綱挈領，立意宏遠。\\\\n\\\\n【名物義理與章法論辯】\\\\n1. 概念範疇與論證推進：全段聚焦「孫卿子曰：知莫大乎棄疑，行莫大乎無過，事莫大乎無悔，……」，荀子善用嚴密之邏輯推理、對比論證與生動譬喻，層層剖析人性自私與社會秩序之建構，論證禮義法度乃聖人積思慮、習偽故所生之社會規範。\\\\n2. 語言風格與先秦散文特色：文氣雄渾博大、句式整飭駢散結合，說理透闢犀利，既重道德禮義之教化，又重功用實效與制度規章。\\\\n\\\\n【經世致用與儒學集大成】\\\\n荀子整合先秦諸子學術精華，兼取法家之法治勢能與墨家之尚賢節用，將儒家仁義思想落實為具體的禮樂刑政與王霸之道，為後世大一統王朝之制度文明與經學思想奠定了堅實根基。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"xunzi_ch-15_p-15\",\"chapterId\":\"xunzi_ch-15\",\"order\":15,\"canonicalText\":\"臨武君曰：善！請問王者之軍制？\",\"sentenceIds\":[\"xunzi_ch-15_p-15_s-1\",\"xunzi_ch-15_p-15_s-2\"],\"sourceRefs\":[{\"label\":\"《荀子》—中國哲學書電子化計劃\",\"edition\":\"王先謙《荀子集解》本\",\"location\":\"https://ctext.org/xunzi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《荀子》—維基文庫\",\"edition\":\"楊倞注《荀子》四部叢刊本\",\"location\":\"https://zh.wikisource.org/zh-hant/荀子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"臨武君說道：善！請問王的人或事物的軍制？\",\"analysis\":\"【荀學篇旨與核心哲思】\\\\n本段選自先秦儒學集大成之作《荀子》〈議兵〉（第 15 節）。文本依據唐楊倞注與清王先謙《荀子集解》之權威學術體系，深刻闡發了荀子「化性起偽」、「隆禮重法」、「明分使羣」與「天行有常」之哲學主旨。開篇「臨武君曰：善」提綱挈領，立意宏遠。\\\\n\\\\n【名物義理與章法論辯】\\\\n1. 概念範疇與論證推進：全段聚焦「臨武君曰：善！請問王者之軍制？」，荀子善用嚴密之邏輯推理、對比論證與生動譬喻，層層剖析人性自私與社會秩序之建構，論證禮義法度乃聖人積思慮、習偽故所生之社會規範。\\\\n2. 語言風格與先秦散文特色：文氣雄渾博大、句式整飭駢散結合，說理透闢犀利，既重道德禮義之教化，又重功用實效與制度規章。\\\\n\\\\n【經世致用與儒學集大成】\\\\n荀子整合先秦諸子學術精華，兼取法家之法治勢能與墨家之尚賢節用，將儒家仁義思想落實為具體的禮樂刑政與王霸之道，為後世大一統王朝之制度文明與經學思想奠定了堅實根基。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"xunzi_ch-15_p-16\",\"chapterId\":\"xunzi_ch-15\",\"order\":16,\"canonicalText\":\"孫卿子曰：將死鼓，御死轡，百吏死職，士大夫死行列。聞鼓聲而進，聞金聲而退，順命為上，有功次之；令不進而進，猶令不退而退也，其罪惟均。不殺老弱，不獵禾稼，服者不禽，格者不捨，奔命者不獲。凡誅，非誅其百姓也，誅其亂百姓者也；百姓有扞其賊，則是亦賊也。以故順刃者生，蘇刃者死，奔命者貢。微子開封於宋，曹觸龍斷於軍，殷之服民，所以養生之者也，無異周人。故近者歌謳而樂之，遠者竭蹙而趨之，無幽閒闢陋之國，莫不趨使而安樂之，四海之內若一家，通達之屬莫不從服，夫是之謂人師。《詩》曰：「自西自東，自南自北，無思不服。」此之謂也。王者有誅而無戰，城守不攻，兵格不擊，上下相喜則慶之，不屠城，不潛軍，不留眾，師不越時。故亂者樂其政，不安其上，欲其至也。\",\"sentenceIds\":[\"xunzi_ch-15_p-16_s-1\",\"xunzi_ch-15_p-16_s-2\",\"xunzi_ch-15_p-16_s-3\",\"xunzi_ch-15_p-16_s-4\",\"xunzi_ch-15_p-16_s-5\",\"xunzi_ch-15_p-16_s-6\",\"xunzi_ch-15_p-16_s-7\",\"xunzi_ch-15_p-16_s-8\",\"xunzi_ch-15_p-16_s-9\",\"xunzi_ch-15_p-16_s-10\",\"xunzi_ch-15_p-16_s-11\",\"xunzi_ch-15_p-16_s-12\",\"xunzi_ch-15_p-16_s-13\"],\"sourceRefs\":[{\"label\":\"《荀子》—中國哲學書電子化計劃\",\"edition\":\"王先謙《荀子集解》本\",\"location\":\"https://ctext.org/xunzi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《荀子》—維基文庫\",\"edition\":\"楊倞注《荀子》四部叢刊本\",\"location\":\"https://zh.wikisource.org/zh-hant/荀子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"孫卿子說道：將死鼓，御死轡，百吏死職，士大夫死行列。聞鼓聲而且進，聞金聲而且退，順命為上，有功次的；令不進而且進，猶令不退而且退啊，他的罪惟均。不殺老弱，不獵禾稼，服的人或事物不禽，格的人或事物不捨，奔命的人或事物不獲。凡誅，絕不是誅他的百姓啊，誅他的亂百姓的人或事物啊；百姓有扞他的賊，則是亦賊啊。以所以順刃的人或事物生，蘇刃的人或事物死，奔命的人或事物貢。微子開封於宋，曹觸龍斷於軍，殷的服民，所以養生的的人或事物啊，無異周人。所以近的人或事物歌謳而且樂的，遠的人或事物竭蹙而且趨的，無幽閒闢陋的國，莫不趨使而且安樂的，四海的內若一家，通達的屬莫不從服，這就是儒家所稱的人師。《詩》說道：自西自東，自南自北，無思不服。此的謂啊。王的人或事物有誅而且無戰，城守不攻，兵格不擊，上下相喜則慶的，不屠城，不潛軍，不留眾，師不越時。所以亂的人或事物樂他的政，不安他的上，欲他的至啊。\",\"analysis\":\"【荀學篇旨與核心哲思】\\\\n本段選自先秦儒學集大成之作《荀子》〈議兵〉（第 16 節）。文本依據唐楊倞注與清王先謙《荀子集解》之權威學術體系，深刻闡發了荀子「化性起偽」、「隆禮重法」、「明分使羣」與「天行有常」之哲學主旨。開篇「孫卿子曰：將死鼓，御死轡，百吏死職，士大夫死行列」提綱挈領，立意宏遠。\\\\n\\\\n【名物義理與章法論辯】\\\\n1. 概念範疇與論證推進：全段聚焦「孫卿子曰：將死鼓，御死轡，百吏死職，士大夫死行列。聞……」，荀子善用嚴密之邏輯推理、對比論證與生動譬喻，層層剖析人性自私與社會秩序之建構，論證禮義法度乃聖人積思慮、習偽故所生之社會規範。\\\\n2. 語言風格與先秦散文特色：文氣雄渾博大、句式整飭駢散結合，說理透闢犀利，既重道德禮義之教化，又重功用實效與制度規章。\\\\n\\\\n【經世致用與儒學集大成】\\\\n荀子整合先秦諸子學術精華，兼取法家之法治勢能與墨家之尚賢節用，將儒家仁義思想落實為具體的禮樂刑政與王霸之道，為後世大一統王朝之制度文明與經學思想奠定了堅實根基。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"xunzi_ch-15_p-17\",\"chapterId\":\"xunzi_ch-15\",\"order\":17,\"canonicalText\":\"臨武君曰：善！\",\"sentenceIds\":[\"xunzi_ch-15_p-17_s-1\"],\"sourceRefs\":[{\"label\":\"《荀子》—中國哲學書電子化計劃\",\"edition\":\"王先謙《荀子集解》本\",\"location\":\"https://ctext.org/xunzi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《荀子》—維基文庫\",\"edition\":\"楊倞注《荀子》四部叢刊本\",\"location\":\"https://zh.wikisource.org/zh-hant/荀子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"臨武君說道：善！\",\"analysis\":\"【荀學篇旨與核心哲思】\\\\n本段選自先秦儒學集大成之作《荀子》〈議兵〉（第 17 節）。文本依據唐楊倞注與清王先謙《荀子集解》之權威學術體系，深刻闡發了荀子「化性起偽」、「隆禮重法」、「明分使羣」與「天行有常」之哲學主旨。開篇「臨武君曰：善」提綱挈領，立意宏遠。\\\\n\\\\n【名物義理與章法論辯】\\\\n1. 概念範疇與論證推進：全段聚焦「臨武君曰：善！」，荀子善用嚴密之邏輯推理、對比論證與生動譬喻，層層剖析人性自私與社會秩序之建構，論證禮義法度乃聖人積思慮、習偽故所生之社會規範。\\\\n2. 語言風格與先秦散文特色：文氣雄渾博大、句式整飭駢散結合，說理透闢犀利，既重道德禮義之教化，又重功用實效與制度規章。\\\\n\\\\n【經世致用與儒學集大成】\\\\n荀子整合先秦諸子學術精華，兼取法家之法治勢能與墨家之尚賢節用，將儒家仁義思想落實為具體的禮樂刑政與王霸之道，為後世大一統王朝之制度文明與經學思想奠定了堅實根基。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"xunzi_ch-15_p-18\",\"chapterId\":\"xunzi_ch-15\",\"order\":18,\"canonicalText\":\"陳囂問孫卿子曰：先生議兵，常以仁義為本；仁者愛人，義者循理，然則又何以兵為？凡所為有兵者，為爭奪也。\",\"sentenceIds\":[\"xunzi_ch-15_p-18_s-1\",\"xunzi_ch-15_p-18_s-2\",\"xunzi_ch-15_p-18_s-3\"],\"sourceRefs\":[{\"label\":\"《荀子》—中國哲學書電子化計劃\",\"edition\":\"王先謙《荀子集解》本\",\"location\":\"https://ctext.org/xunzi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《荀子》—維基文庫\",\"edition\":\"楊倞注《荀子》四部叢刊本\",\"location\":\"https://zh.wikisource.org/zh-hant/荀子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"陳囂問孫卿子說道：先生議兵，常以仁愛慈悲之德正義道義為本；仁愛慈悲之德的人或事物愛人，正義道義的人或事物循理，然則又何以兵為？凡所為有兵的人或事物，為爭奪啊。\",\"analysis\":\"【荀學篇旨與核心哲思】\\\\n本段選自先秦儒學集大成之作《荀子》〈議兵〉（第 18 節）。文本依據唐楊倞注與清王先謙《荀子集解》之權威學術體系，深刻闡發了荀子「化性起偽」、「隆禮重法」、「明分使羣」與「天行有常」之哲學主旨。開篇「陳囂問孫卿子曰：先生議兵，常以仁義為本」提綱挈領，立意宏遠。\\\\n\\\\n【名物義理與章法論辯】\\\\n1. 概念範疇與論證推進：全段聚焦「陳囂問孫卿子曰：先生議兵，常以仁義為本；仁者愛人，義……」，荀子善用嚴密之邏輯推理、對比論證與生動譬喻，層層剖析人性自私與社會秩序之建構，論證禮義法度乃聖人積思慮、習偽故所生之社會規範。\\\\n2. 語言風格與先秦散文特色：文氣雄渾博大、句式整飭駢散結合，說理透闢犀利，既重道德禮義之教化，又重功用實效與制度規章。\\\\n\\\\n【經世致用與儒學集大成】\\\\n荀子整合先秦諸子學術精華，兼取法家之法治勢能與墨家之尚賢節用，將儒家仁義思想落實為具體的禮樂刑政與王霸之道，為後世大一統王朝之制度文明與經學思想奠定了堅實根基。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"xunzi_ch-15_p-19\",\"chapterId\":\"xunzi_ch-15\",\"order\":19,\"canonicalText\":\"孫卿子曰：非汝所知也！彼仁者愛人，愛人故惡人之害之也；義者循理，循理故惡人之亂之也。彼兵者所以禁暴除害也，非爭奪也。故仁者之兵，所存者神，所過者化，若時雨之降，莫不說喜。是以堯伐驩兜，舜伐有苗，禹伐共工，湯伐有夏，文王伐崇，武王伐紂，此四帝兩王，皆以仁義之兵，行於天下也。故近者親其善，遠方慕其德，兵不血刃，遠邇來服，德盛於此，施及四極。《詩》曰：「淑人君子，其儀不忒。」此之謂也。\",\"sentenceIds\":[\"xunzi_ch-15_p-19_s-1\",\"xunzi_ch-15_p-19_s-2\",\"xunzi_ch-15_p-19_s-3\",\"xunzi_ch-15_p-19_s-4\",\"xunzi_ch-15_p-19_s-5\",\"xunzi_ch-15_p-19_s-6\",\"xunzi_ch-15_p-19_s-7\",\"xunzi_ch-15_p-19_s-8\",\"xunzi_ch-15_p-19_s-9\"],\"sourceRefs\":[{\"label\":\"《荀子》—中國哲學書電子化計劃\",\"edition\":\"王先謙《荀子集解》本\",\"location\":\"https://ctext.org/xunzi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《荀子》—維基文庫\",\"edition\":\"楊倞注《荀子》四部叢刊本\",\"location\":\"https://zh.wikisource.org/zh-hant/荀子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"孫卿子說道：絕不是汝所知啊！彼仁愛慈悲之德的人或事物愛人，愛人所以惡人的害的啊；正義道義的人或事物循理，循理所以惡人的亂的啊。彼兵的人或事物所以禁暴除害啊，絕不是爭奪啊。所以仁愛慈悲之德的人或事物的兵，所存的人或事物神，所過的人或事物化，若時雨的降，莫不說喜。是以堯伐驩兜，舜伐有苗，禹伐共工，湯伐有夏，文王伐崇，武王伐紂，此四帝兩王，皆以仁愛慈悲之德正義道義的兵，行於天下啊。所以近的人或事物親他的善，遠方慕他的品德修養，兵不血刃，遠邇來服，品德修養盛於此，施及四極。《詩》說道：淑人君子，他的儀不忒。此的謂啊。\",\"analysis\":\"【荀學篇旨與核心哲思】\\\\n本段選自先秦儒學集大成之作《荀子》〈議兵〉（第 19 節）。文本依據唐楊倞注與清王先謙《荀子集解》之權威學術體系，深刻闡發了荀子「化性起偽」、「隆禮重法」、「明分使羣」與「天行有常」之哲學主旨。開篇「孫卿子曰：非汝所知也」提綱挈領，立意宏遠。\\\\n\\\\n【名物義理與章法論辯】\\\\n1. 概念範疇與論證推進：全段聚焦「孫卿子曰：非汝所知也！彼仁者愛人，愛人故惡人之害之也……」，荀子善用嚴密之邏輯推理、對比論證與生動譬喻，層層剖析人性自私與社會秩序之建構，論證禮義法度乃聖人積思慮、習偽故所生之社會規範。\\\\n2. 語言風格與先秦散文特色：文氣雄渾博大、句式整飭駢散結合，說理透闢犀利，既重道德禮義之教化，又重功用實效與制度規章。\\\\n\\\\n【經世致用與儒學集大成】\\\\n荀子整合先秦諸子學術精華，兼取法家之法治勢能與墨家之尚賢節用，將儒家仁義思想落實為具體的禮樂刑政與王霸之道，為後世大一統王朝之制度文明與經學思想奠定了堅實根基。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"xunzi_ch-15_p-20\",\"chapterId\":\"xunzi_ch-15\",\"order\":20,\"canonicalText\":\"李斯問孫卿子曰：秦四世有勝，兵強海內，威行諸侯，非以仁義為之也，以便從事而已。\",\"sentenceIds\":[\"xunzi_ch-15_p-20_s-1\"],\"sourceRefs\":[{\"label\":\"《荀子》—中國哲學書電子化計劃\",\"edition\":\"王先謙《荀子集解》本\",\"location\":\"https://ctext.org/xunzi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《荀子》—維基文庫\",\"edition\":\"楊倞注《荀子》四部叢刊本\",\"location\":\"https://zh.wikisource.org/zh-hant/荀子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"李斯問孫卿子說道：秦四世有勝，兵強海內，威行諸侯，絕不是以仁愛慈悲之德正義道義為的啊，以便從事而且已。\",\"analysis\":\"【荀學篇旨與核心哲思】\\\\n本段選自先秦儒學集大成之作《荀子》〈議兵〉（第 20 節）。文本依據唐楊倞注與清王先謙《荀子集解》之權威學術體系，深刻闡發了荀子「化性起偽」、「隆禮重法」、「明分使羣」與「天行有常」之哲學主旨。開篇「李斯問孫卿子曰：秦四世有勝，兵強海內，威行諸侯，非以仁義為之也，以便從事而已」提綱挈領，立意宏遠。\\\\n\\\\n【名物義理與章法論辯】\\\\n1. 概念範疇與論證推進：全段聚焦「李斯問孫卿子曰：秦四世有勝，兵強海內，威行諸侯，非以……」，荀子善用嚴密之邏輯推理、對比論證與生動譬喻，層層剖析人性自私與社會秩序之建構，論證禮義法度乃聖人積思慮、習偽故所生之社會規範。\\\\n2. 語言風格與先秦散文特色：文氣雄渾博大、句式整飭駢散結合，說理透闢犀利，既重道德禮義之教化，又重功用實效與制度規章。\\\\n\\\\n【經世致用與儒學集大成】\\\\n荀子整合先秦諸子學術精華，兼取法家之法治勢能與墨家之尚賢節用，將儒家仁義思想落實為具體的禮樂刑政與王霸之道，為後世大一統王朝之制度文明與經學思想奠定了堅實根基。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"xunzi_ch-15_p-21\",\"chapterId\":\"xunzi_ch-15\",\"order\":21,\"canonicalText\":\"孫卿子曰：非汝所知也！汝所謂便者，不便之便也；吾所謂仁義者，大便之便也。彼仁義者，所以脩政者也；政脩則民親其上，樂其君，而輕為之死。故曰：凡在於軍，將率末事也。秦四世有勝，諰諰然常恐天下之一合而軋己也，此所謂末世之兵，未有本統也。故湯之放桀也，非其逐之鳴條之時也；武王之誅紂也，非以甲子之朝而後勝之也，皆前行素脩也，所謂仁義之兵也。今女不求之於本，而索之於末，此世之所以亂也。\",\"sentenceIds\":[\"xunzi_ch-15_p-21_s-1\",\"xunzi_ch-15_p-21_s-2\",\"xunzi_ch-15_p-21_s-3\",\"xunzi_ch-15_p-21_s-4\",\"xunzi_ch-15_p-21_s-5\",\"xunzi_ch-15_p-21_s-6\",\"xunzi_ch-15_p-21_s-7\",\"xunzi_ch-15_p-21_s-8\",\"xunzi_ch-15_p-21_s-9\",\"xunzi_ch-15_p-21_s-10\"],\"sourceRefs\":[{\"label\":\"《荀子》—中國哲學書電子化計劃\",\"edition\":\"王先謙《荀子集解》本\",\"location\":\"https://ctext.org/xunzi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《荀子》—維基文庫\",\"edition\":\"楊倞注《荀子》四部叢刊本\",\"location\":\"https://zh.wikisource.org/zh-hant/荀子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"孫卿子說道：絕不是汝所知啊！汝所謂便的人或事物，不便的便啊；吾所謂仁愛慈悲之德正義道義的人或事物，大便的便啊。彼仁愛慈悲之德正義道義的人或事物，所以脩政的人或事物啊；政脩則民親他的上，樂他的君，而且輕為的死。所以古聖先賢說道：凡在於軍，將率末事啊。秦四世有勝，諰諰然常恐天下的一合而且軋己啊，此所謂末世的兵，未有本統啊。所以湯的放桀啊，絕不是他的逐的鳴條的時啊；武王的誅紂啊，絕不是以甲子的朝而且後勝的啊，皆前行素脩啊，所謂仁愛慈悲之德正義道義的兵啊。今女不求的於本，而且索的於末，此世的所以亂啊。\",\"analysis\":\"【荀學篇旨與核心哲思】\\\\n本段選自先秦儒學集大成之作《荀子》〈議兵〉（第 21 節）。文本依據唐楊倞注與清王先謙《荀子集解》之權威學術體系，深刻闡發了荀子「化性起偽」、「隆禮重法」、「明分使羣」與「天行有常」之哲學主旨。開篇「孫卿子曰：非汝所知也」提綱挈領，立意宏遠。\\\\n\\\\n【名物義理與章法論辯】\\\\n1. 概念範疇與論證推進：全段聚焦「孫卿子曰：非汝所知也！汝所謂便者，不便之便也；吾所謂……」，荀子善用嚴密之邏輯推理、對比論證與生動譬喻，層層剖析人性自私與社會秩序之建構，論證禮義法度乃聖人積思慮、習偽故所生之社會規範。\\\\n2. 語言風格與先秦散文特色：文氣雄渾博大、句式整飭駢散結合，說理透闢犀利，既重道德禮義之教化，又重功用實效與制度規章。\\\\n\\\\n【經世致用與儒學集大成】\\\\n荀子整合先秦諸子學術精華，兼取法家之法治勢能與墨家之尚賢節用，將儒家仁義思想落實為具體的禮樂刑政與王霸之道，為後世大一統王朝之制度文明與經學思想奠定了堅實根基。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"xunzi_ch-15_p-22\",\"chapterId\":\"xunzi_ch-15\",\"order\":22,\"canonicalText\":\"禮者、治辨之極也，強固之本也，威行之道也，功名之總也，王公由之所以得天下也，不由所以隕社稷也。故堅甲利兵不足以為勝，高城深池不足以為固，嚴令繁刑不足以為威。由其道則行，不由其道則廢。\",\"sentenceIds\":[\"xunzi_ch-15_p-22_s-1\",\"xunzi_ch-15_p-22_s-2\",\"xunzi_ch-15_p-22_s-3\"],\"sourceRefs\":[{\"label\":\"《荀子》—中國哲學書電子化計劃\",\"edition\":\"王先謙《荀子集解》本\",\"location\":\"https://ctext.org/xunzi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《荀子》—維基文庫\",\"edition\":\"楊倞注《荀子》四部叢刊本\",\"location\":\"https://zh.wikisource.org/zh-hant/荀子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"禮正義道義道品德修養規程的人或事物、治辨的極啊，強固的本啊，威行的道啊，功名的總啊，王公由的所以得天下啊，不由所以隕社稷啊。所以堅甲利兵不足以為勝，高城深池不足以為固，嚴令繁刑不足以為威。由他的道則行，不由他的道則廢。\",\"analysis\":\"【荀學篇旨與核心哲思】\\\\n本段選自先秦儒學集大成之作《荀子》〈議兵〉（第 22 節）。文本依據唐楊倞注與清王先謙《荀子集解》之權威學術體系，深刻闡發了荀子「化性起偽」、「隆禮重法」、「明分使羣」與「天行有常」之哲學主旨。開篇「禮者、治辨之極也，強固之本也，威行之道也，功名之總也，王公由之所以得天下也，不由所以隕社稷也」提綱挈領，立意宏遠。\\\\n\\\\n【名物義理與章法論辯】\\\\n1. 概念範疇與論證推進：全段聚焦「禮者、治辨之極也，強固之本也，威行之道也，功名之總也……」，荀子善用嚴密之邏輯推理、對比論證與生動譬喻，層層剖析人性自私與社會秩序之建構，論證禮義法度乃聖人積思慮、習偽故所生之社會規範。\\\\n2. 語言風格與先秦散文特色：文氣雄渾博大、句式整飭駢散結合，說理透闢犀利，既重道德禮義之教化，又重功用實效與制度規章。\\\\n\\\\n【經世致用與儒學集大成】\\\\n荀子整合先秦諸子學術精華，兼取法家之法治勢能與墨家之尚賢節用，將儒家仁義思想落實為具體的禮樂刑政與王霸之道，為後世大一統王朝之制度文明與經學思想奠定了堅實根基。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"xunzi_ch-15_p-23\",\"chapterId\":\"xunzi_ch-15\",\"order\":23,\"canonicalText\":\"楚人鮫革犀兕以為甲，鞈堅如金石；宛鉅鐵矛，慘如蜂蠆，輕利僄遫，卒如飄風；然而兵殆於垂沙，唐蔑死。莊蹻起，楚分而為三四，是豈無堅甲利兵也哉！其所以統之者非其道故也。汝潁以為險，江漢以為池，限之以鄧林，緣之以方城；然而秦師至，而鄢郢舉，若振槁然，是豈無固塞隘阻也哉！其所以統之者非其道故也。紂刳比干，囚箕子，為炮烙刑，殺戮無時，臣下懍然莫必其命，然而周師至，而令不行乎下，不能用其民，是豈令不嚴，刑不繁也哉！其所以統之者非其道故也。\",\"sentenceIds\":[\"xunzi_ch-15_p-23_s-1\",\"xunzi_ch-15_p-23_s-2\",\"xunzi_ch-15_p-23_s-3\",\"xunzi_ch-15_p-23_s-4\",\"xunzi_ch-15_p-23_s-5\",\"xunzi_ch-15_p-23_s-6\",\"xunzi_ch-15_p-23_s-7\",\"xunzi_ch-15_p-23_s-8\",\"xunzi_ch-15_p-23_s-9\",\"xunzi_ch-15_p-23_s-10\"],\"sourceRefs\":[{\"label\":\"《荀子》—中國哲學書電子化計劃\",\"edition\":\"王先謙《荀子集解》本\",\"location\":\"https://ctext.org/xunzi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《荀子》—維基文庫\",\"edition\":\"楊倞注《荀子》四部叢刊本\",\"location\":\"https://zh.wikisource.org/zh-hant/荀子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"楚國人用鯊魚皮和犀牛皮做成鎧甲，堅硬得像金屬和石頭；使用宛地生產的精良鐵矛，毒烈得像蜜蜂和蠍子的尾刺，軍隊裝備輕便銳利、行動迅速，士兵衝鋒起來就像狂風一樣；然而楚軍卻在垂沙之戰中慘敗，主將唐蔑戰死。莊蹻發動叛亂，楚國四分五裂，難道是因為沒有堅固的鎧甲和鋒利的兵器嗎？是因為他們統御軍隊的方法不符合王道啊。楚國把汝水和潁水當作天險，把長江和漢水當作護城河，以鄧林作為邊界的屏障，沿著方城山修築防線；然而秦國軍隊一到，鄢、郢兩座都城就被攻克，就像搖落枯槁的樹葉一樣容易，難道是因為沒有堅固的要塞和險阻嗎？是因為他們統治國家的方法不符合王道啊。商紂王剖開比干的心，囚禁了箕子，設置了殘酷的炮烙之刑，殺戮沒有節制，臣子們恐懼得無法保證自己的性命，然而周武王的軍隊一到，商紂王的命令就無法下達，無法驅使他的百姓作戰，難道是因為命令不嚴厲、刑罰不繁多嗎？是因為他統治天下的方法不符合王道啊。\",\"analysis\":\"【訓詁與名物】「鮫革犀兕」指用鯊魚皮和犀牛皮製成的鎧甲。「鞈」通「甲」。「宛鉅鐵矛」指宛地（南陽）出產的精良鐵矛。「蜂蠆」指蜜蜂與蠍子，比喻兵器有毒且銳利。「僄遫」指輕快敏捷。「振槁」指搖落枯槁的樹葉，比喻極其容易。「刳」指剖開。\\\\n【章法與結構】本段採取了極其工整的排比句式，連舉三個歷史案例（楚軍裝備精良卻敗於垂沙、楚國地勢險要卻失守鄢郢、商紂刑罰嚴酷卻亡國）。每個案例皆先極力鋪陳其優勢（兵器、地形、嚴刑），接著以「然而」發生轉折敘述其慘敗，最後以「是豈無……哉！其所以統之者非其道故也」作為一致的結語，論證層層推進，氣勢如虹。\\\\n【思想與義理】這段文字充分展現了荀子反對單純迷信武力、地形與嚴刑峻法的王道思想。荀子認為，堅甲利兵、險要地勢或嚴酷刑罰都只是外在的物質與手段，如果統治者背離了「道」（即仁義禮治），失去了民心與正當性，這些外在優勢都將毫無用處。治國與治軍的核心，始終在於政治的清明與人心的歸附。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"xunzi_ch-15_p-24\",\"chapterId\":\"xunzi_ch-15\",\"order\":24,\"canonicalText\":\"古之兵，戈矛弓矢而已矣，然而敵國不待試而詘；城郭不辨，溝池不抇，固塞不樹，機變不張；然而國晏然不畏外而固者，無它故焉，明道而鈞分之，時使而誠愛之，下之和上也如影嚮，有不由令者，然後俟之以刑。故刑一人而天下服，罪人不郵其上，知罪之在己也。是故刑罰省而威流，無它故焉，由其道故也。古者帝堯之治天下也，蓋殺一人，刑二人，而天下治。傳曰：「威厲而不試，刑錯而不用。」此之謂也。\",\"sentenceIds\":[\"xunzi_ch-15_p-24_s-1\",\"xunzi_ch-15_p-24_s-2\",\"xunzi_ch-15_p-24_s-3\",\"xunzi_ch-15_p-24_s-4\",\"xunzi_ch-15_p-24_s-5\",\"xunzi_ch-15_p-24_s-6\",\"xunzi_ch-15_p-24_s-7\",\"xunzi_ch-15_p-24_s-8\"],\"sourceRefs\":[{\"label\":\"《荀子》—中國哲學書電子化計劃\",\"edition\":\"王先謙《荀子集解》本\",\"location\":\"https://ctext.org/xunzi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《荀子》—維基文庫\",\"edition\":\"楊倞注《荀子》四部叢刊本\",\"location\":\"https://zh.wikisource.org/zh-hant/荀子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"古的兵，戈矛弓矢而且已矣，然而且敵國不待試而且詘；城郭不辨，溝池不抇，固塞不樹，機變不張；然而且國晏然不畏外而且固的人或事物，無它所以焉，明道而且鈞分的，時使而且誠愛的，下的和上啊如影嚮，有不由令的人或事物，然後俟的以刑。所以刑一人而且天下服，罪人不郵他的上，知罪的在己啊。正因為如此刑罰省而且威流，無它所以焉，由他的道所以啊。古的人或事物帝堯的治天下啊，蓋殺一人，刑二人，而且天下治。傳說道：威厲而且不試，刑錯而且不用。此的謂啊。\",\"analysis\":\"【荀學篇旨與核心哲思】\\\\n本段選自先秦儒學集大成之作《荀子》〈議兵〉（第 24 節）。文本依據唐楊倞注與清王先謙《荀子集解》之權威學術體系，深刻闡發了荀子「化性起偽」、「隆禮重法」、「明分使羣」與「天行有常」之哲學主旨。開篇「古之兵，戈矛弓矢而已矣，然而敵國不待試而詘」提綱挈領，立意宏遠。\\\\n\\\\n【名物義理與章法論辯】\\\\n1. 概念範疇與論證推進：全段聚焦「古之兵，戈矛弓矢而已矣，然而敵國不待試而詘；城郭不辨……」，荀子善用嚴密之邏輯推理、對比論證與生動譬喻，層層剖析人性自私與社會秩序之建構，論證禮義法度乃聖人積思慮、習偽故所生之社會規範。\\\\n2. 語言風格與先秦散文特色：文氣雄渾博大、句式整飭駢散結合，說理透闢犀利，既重道德禮義之教化，又重功用實效與制度規章。\\\\n\\\\n【經世致用與儒學集大成】\\\\n荀子整合先秦諸子學術精華，兼取法家之法治勢能與墨家之尚賢節用，將儒家仁義思想落實為具體的禮樂刑政與王霸之道，為後世大一統王朝之制度文明與經學思想奠定了堅實根基。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"xunzi_ch-15_p-25\",\"chapterId\":\"xunzi_ch-15\",\"order\":25,\"canonicalText\":\"凡人之動也，為賞慶為之，則見害傷焉止矣。故賞慶、刑罰、埶詐，不足以盡人之力，致人之死。為人主上者也，其所以接下之百姓者，無禮義忠信，焉慮率用賞慶、刑罰、埶詐，除阨其下，獲其功用而已矣。大寇則至，使之持危城則必畔，遇敵處戰則必北，勞苦煩辱則必奔，霍焉離耳，下反制其上。故賞慶、刑罰、埶詐之為道者，傭徒鬻賣之道也，不足以合大眾，美國家，故古之人羞而不道也。故厚德音以先之，明禮義以道之，致忠信以愛之，尚賢使能以次之，爵服慶賞以申之，時其事，輕其任，以調齊之，長養之，如保赤子。政令以定，風俗以一，有離俗不順其上，則百姓莫不敦惡，莫不毒孽，若祓不祥；然後刑於是起矣。是大刑之所加也，辱孰大焉！將以為利邪？則大刑加焉，身苟不狂惑戇陋，誰睹是而不改也哉！然後百姓曉然皆知循上之法，像上之志，而安樂之。於是有能化善、脩身、正行、積禮義、尊道德，百姓莫不貴敬，莫不親譽；然後賞於是起矣。是高爵豐祿之所加也，榮孰大焉！將以為害邪？則高爵豐祿以持養之；生民之屬，孰不願也！雕雕焉縣貴爵重賞於其前，縣明刑大辱於其後，雖欲無化，能乎哉！故民歸之如流水，所存者神，所為者化，而順，暴悍勇力之屬為之化而願，旁闢曲私之屬為之化而公，矜糾收繚之屬為之化而調，夫是之謂大化至一。《詩》曰：「王猶允塞，徐方既來。」此之謂也。\",\"sentenceIds\":[\"xunzi_ch-15_p-25_s-1\",\"xunzi_ch-15_p-25_s-2\",\"xunzi_ch-15_p-25_s-3\",\"xunzi_ch-15_p-25_s-4\",\"xunzi_ch-15_p-25_s-5\",\"xunzi_ch-15_p-25_s-6\",\"xunzi_ch-15_p-25_s-7\",\"xunzi_ch-15_p-25_s-8\",\"xunzi_ch-15_p-25_s-9\",\"xunzi_ch-15_p-25_s-10\",\"xunzi_ch-15_p-25_s-11\",\"xunzi_ch-15_p-25_s-12\",\"xunzi_ch-15_p-25_s-13\",\"xunzi_ch-15_p-25_s-14\",\"xunzi_ch-15_p-25_s-15\",\"xunzi_ch-15_p-25_s-16\",\"xunzi_ch-15_p-25_s-17\",\"xunzi_ch-15_p-25_s-18\",\"xunzi_ch-15_p-25_s-19\",\"xunzi_ch-15_p-25_s-20\",\"xunzi_ch-15_p-25_s-21\",\"xunzi_ch-15_p-25_s-22\"],\"sourceRefs\":[{\"label\":\"《荀子》—中國哲學書電子化計劃\",\"edition\":\"王先謙《荀子集解》本\",\"location\":\"https://ctext.org/xunzi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《荀子》—維基文庫\",\"edition\":\"楊倞注《荀子》四部叢刊本\",\"location\":\"https://zh.wikisource.org/zh-hant/荀子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"凡人的動啊，為賞慶為的，則見害傷焉止矣。所以賞慶、刑罰、埶詐，不足以盡人的力，致人的死。為人主上的人或事物啊，他的所以接下的百姓的人或事物，無禮正義道義道品德修養規程正義道義忠信，焉慮率用賞慶、刑罰、埶詐，除阨他的下，獲他的功用而且已矣。大寇則至，使的持危城則必畔，遇敵處戰則必北，勞苦煩辱則必奔，霍焉離耳，下反制他的上。所以賞慶、刑罰、埶詐的為道的人或事物，傭徒鬻賣的道啊，不足以合大眾，美國家，所以古的人羞而且不道啊。所以厚品德修養音以先的，明禮正義道義道品德修養規程正義道義以道的，致忠信以愛的，尚賢使能以次的，爵服慶賞以申的，時他的事，輕他的任，以調齊的，長養的，如保赤子。政令以定，風俗以一，有離俗不順他的上，則百姓莫不敦惡，莫不毒孽，若祓不祥；然後刑於是起矣。是大刑的所加啊，辱孰大焉！將以為利邪？則大刑加焉，身苟不狂惑戇陋，誰睹是而且不改啊哉！然後百姓曉然皆知循上的國家典章法度，像上的志，而且安樂的。於是有能化善、脩身、正行、積禮正義道義道品德修養規程正義道義、尊道品德修養，百姓莫不貴敬，莫不親譽；然後賞於是起矣。是高爵豐祿的所加啊，榮孰大焉！將以為害邪？則高爵豐祿以持養的；生民的屬，孰不願啊！雕雕焉縣貴爵重賞於他的前，縣明刑大辱於他的後，雖欲無化，能乎哉！所以民歸的如流水，所存的人或事物神，所為的人或事物化，而且順，暴悍勇力的屬為的化而且願，旁闢曲私的屬為的化而且公，矜糾收繚的屬為的化而且調，這就是儒家所稱的大化至一。《詩》說道：王猶允塞，徐方既來。此的謂啊。\",\"analysis\":\"【荀學篇旨與核心哲思】\\\\n本段選自先秦儒學集大成之作《荀子》〈議兵〉（第 25 節）。文本依據唐楊倞注與清王先謙《荀子集解》之權威學術體系，深刻闡發了荀子「化性起偽」、「隆禮重法」、「明分使羣」與「天行有常」之哲學主旨。開篇「凡人之動也，為賞慶為之，則見害傷焉止矣」提綱挈領，立意宏遠。\\\\n\\\\n【名物義理與章法論辯】\\\\n1. 概念範疇與論證推進：全段聚焦「凡人之動也，為賞慶為之，則見害傷焉止矣。故賞慶、刑罰……」，荀子善用嚴密之邏輯推理、對比論證與生動譬喻，層層剖析人性自私與社會秩序之建構，論證禮義法度乃聖人積思慮、習偽故所生之社會規範。\\\\n2. 語言風格與先秦散文特色：文氣雄渾博大、句式整飭駢散結合，說理透闢犀利，既重道德禮義之教化，又重功用實效與制度規章。\\\\n\\\\n【經世致用與儒學集大成】\\\\n荀子整合先秦諸子學術精華，兼取法家之法治勢能與墨家之尚賢節用，將儒家仁義思想落實為具體的禮樂刑政與王霸之道，為後世大一統王朝之制度文明與經學思想奠定了堅實根基。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"xunzi_ch-15_p-26\",\"chapterId\":\"xunzi_ch-15\",\"order\":26,\"canonicalText\":\"凡兼人者有三術：有以德兼人者，有以力兼人者，有以富兼人者。彼貴我名聲，美我德行，欲為我民，故闢門除塗，以迎吾入。因其民，襲其處，而百姓皆安。立法施令，莫不順比。是故得地而權彌重，兼人而兵俞強：是以德兼人者也。非貴我名聲也，非美我德行也，彼畏我威，劫我埶，故民雖有離心，不敢有畔慮，若是則戎甲俞眾，奉養必費。是故得地而權彌輕，兼人而兵俞弱：是以力兼人者也。非貴我名聲也，非美我德行也，用貧求富，用飢求飽，虛腹張口，來歸我食。若是，則必發夫掌窌之粟以食之，委之財貨以富之，立良有司以接之，已期三年，然後民可信也。是故得地而權彌輕，兼人而國俞貧：是以富兼人者也。故曰：以德兼人者王，以力兼人者弱，以富兼人者貧，古今一也。\",\"sentenceIds\":[\"xunzi_ch-15_p-26_s-1\",\"xunzi_ch-15_p-26_s-2\",\"xunzi_ch-15_p-26_s-3\",\"xunzi_ch-15_p-26_s-4\",\"xunzi_ch-15_p-26_s-5\",\"xunzi_ch-15_p-26_s-6\",\"xunzi_ch-15_p-26_s-7\",\"xunzi_ch-15_p-26_s-8\",\"xunzi_ch-15_p-26_s-9\",\"xunzi_ch-15_p-26_s-10\",\"xunzi_ch-15_p-26_s-11\"],\"sourceRefs\":[{\"label\":\"《荀子》—中國哲學書電子化計劃\",\"edition\":\"王先謙《荀子集解》本\",\"location\":\"https://ctext.org/xunzi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《荀子》—維基文庫\",\"edition\":\"楊倞注《荀子》四部叢刊本\",\"location\":\"https://zh.wikisource.org/zh-hant/荀子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"凡兼人的人或事物有三術：有以品德修養兼人的人或事物，有以力兼人的人或事物，有以富兼人的人或事物。彼貴我名聲，美我品德修養行，欲為我民，所以闢門除塗，以迎吾入。因他的民，襲他的處，而且百姓皆安。立國家典章法度施令，莫不順比。正因為如此得地而且權彌重，兼人而且兵俞強：是以品德修養兼人的人或事物啊。絕不是貴我名聲啊，絕不是美我品德修養行啊，彼畏我威，劫我埶，所以民雖有離心，不敢有畔慮，若是則戎甲俞眾，奉養必費。正因為如此得地而且權彌輕，兼人而且兵俞弱：是以力兼人的人或事物啊。絕不是貴我名聲啊，絕不是美我品德修養行啊，用貧求富，用飢求飽，虛腹張口，來歸我食。若是，則必發夫掌窌的粟以食的，委的財貨以富的，立良有司以接的，已期三年，然後民可信啊。正因為如此得地而且權彌輕，兼人而且國俞貧：是以富兼人的人或事物啊。所以古聖先賢說道：以品德修養兼人的人或事物王，以力兼人的人或事物弱，以富兼人的人或事物貧，古今一啊。\",\"analysis\":\"【荀學篇旨與核心哲思】\\\\n本段選自先秦儒學集大成之作《荀子》〈議兵〉（第 26 節）。文本依據唐楊倞注與清王先謙《荀子集解》之權威學術體系，深刻闡發了荀子「化性起偽」、「隆禮重法」、「明分使羣」與「天行有常」之哲學主旨。開篇「凡兼人者有三術：有以德兼人者，有以力兼人者，有以富兼人者」提綱挈領，立意宏遠。\\\\n\\\\n【名物義理與章法論辯】\\\\n1. 概念範疇與論證推進：全段聚焦「凡兼人者有三術：有以德兼人者，有以力兼人者，有以富兼……」，荀子善用嚴密之邏輯推理、對比論證與生動譬喻，層層剖析人性自私與社會秩序之建構，論證禮義法度乃聖人積思慮、習偽故所生之社會規範。\\\\n2. 語言風格與先秦散文特色：文氣雄渾博大、句式整飭駢散結合，說理透闢犀利，既重道德禮義之教化，又重功用實效與制度規章。\\\\n\\\\n【經世致用與儒學集大成】\\\\n荀子整合先秦諸子學術精華，兼取法家之法治勢能與墨家之尚賢節用，將儒家仁義思想落實為具體的禮樂刑政與王霸之道，為後世大一統王朝之制度文明與經學思想奠定了堅實根基。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"xunzi_ch-15_p-27\",\"chapterId\":\"xunzi_ch-15\",\"order\":27,\"canonicalText\":\"兼併易能也，唯堅凝之難焉。齊能並宋，而不能凝也，故魏奪之。燕能並齊，而不能凝也，故田單奪之。韓之上地，方數百里，完全富足而趨趙，趙不能凝也，故秦奪之。故能並之，而不能凝，則必奪；不能並之，又不能凝其有，則必亡。能凝之，則必能並之矣。得之則凝，兼併無強。古者湯以薄，武王以滈，皆百里之地也，天下為一，諸侯為臣，無他故焉，能凝之也。故凝士以禮，凝民以政；禮脩而士服，政平而民安；士服民安，夫是之謂大凝。以守則固，以徵則強，令行禁止，王者之事畢矣。\",\"sentenceIds\":[\"xunzi_ch-15_p-27_s-1\",\"xunzi_ch-15_p-27_s-2\",\"xunzi_ch-15_p-27_s-3\",\"xunzi_ch-15_p-27_s-4\",\"xunzi_ch-15_p-27_s-5\",\"xunzi_ch-15_p-27_s-6\",\"xunzi_ch-15_p-27_s-7\",\"xunzi_ch-15_p-27_s-8\",\"xunzi_ch-15_p-27_s-9\",\"xunzi_ch-15_p-27_s-10\",\"xunzi_ch-15_p-27_s-11\",\"xunzi_ch-15_p-27_s-12\",\"xunzi_ch-15_p-27_s-13\"],\"sourceRefs\":[{\"label\":\"《荀子》—中國哲學書電子化計劃\",\"edition\":\"王先謙《荀子集解》本\",\"location\":\"https://ctext.org/xunzi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《荀子》—維基文庫\",\"edition\":\"楊倞注《荀子》四部叢刊本\",\"location\":\"https://zh.wikisource.org/zh-hant/荀子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"兼併易能啊，唯堅凝的難焉。齊能並宋，而且不能凝啊，所以魏奪的。燕能並齊，而且不能凝啊，所以田單奪的。韓的上地，方數百里，完全富足而且趨趙，趙不能凝啊，所以秦奪的。所以能並的，而且不能凝，則必奪；不能並的，又不能凝他的有，則必亡。能凝的，則必能並的矣。得的則凝，兼併無強。古的人或事物湯以薄，武王以滈，皆百里的地啊，天下為一，諸侯為臣，無他所以焉，能凝的啊。所以凝士以禮正義道義道品德修養規程，凝民以政；禮正義道義道品德修養規程脩而且士服，政平而且民安；士服民安，這就是儒家所稱的大凝。以守則固，以徵則強，令行禁止，王的人或事物的事畢矣。\",\"analysis\":\"【荀學篇旨與核心哲思】\\\\n本段選自先秦儒學集大成之作《荀子》〈議兵〉（第 27 節）。文本依據唐楊倞注與清王先謙《荀子集解》之權威學術體系，深刻闡發了荀子「化性起偽」、「隆禮重法」、「明分使羣」與「天行有常」之哲學主旨。開篇「兼併易能也，唯堅凝之難焉」提綱挈領，立意宏遠。\\\\n\\\\n【名物義理與章法論辯】\\\\n1. 概念範疇與論證推進：全段聚焦「兼併易能也，唯堅凝之難焉。齊能並宋，而不能凝也，故魏……」，荀子善用嚴密之邏輯推理、對比論證與生動譬喻，層層剖析人性自私與社會秩序之建構，論證禮義法度乃聖人積思慮、習偽故所生之社會規範。\\\\n2. 語言風格與先秦散文特色：文氣雄渾博大、句式整飭駢散結合，說理透闢犀利，既重道德禮義之教化，又重功用實效與制度規章。\\\\n\\\\n【經世致用與儒學集大成】\\\\n荀子整合先秦諸子學術精華，兼取法家之法治勢能與墨家之尚賢節用，將儒家仁義思想落實為具體的禮樂刑政與王霸之道，為後世大一統王朝之制度文明與經學思想奠定了堅實根基。\",\"historicalContext\":\"\",\"keywords\":[]}}],\"sentences\":[{\"id\":\"xunzi_ch-15_p-1_s-1\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-15\",\"passageId\":\"xunzi_ch-15_p-1\",\"order\":1,\"canonicalText\":\"臨武君與孫卿子議兵於趙孝成王前，王曰：請問兵要？\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-15_p-2_s-1\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-15\",\"passageId\":\"xunzi_ch-15_p-2\",\"order\":1,\"canonicalText\":\"臨武君對曰：上得天時，下得地利，觀敵之變動，後之發，先之至，此用兵之要術也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-15_p-3_s-1\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-15\",\"passageId\":\"xunzi_ch-15_p-3\",\"order\":1,\"canonicalText\":\"孫卿子曰：不然！\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-15_p-3_s-2\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-15\",\"passageId\":\"xunzi_ch-15_p-3\",\"order\":2,\"canonicalText\":\"臣所聞古之道，凡用兵攻戰之本，在乎壹民。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-15_p-3_s-3\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-15\",\"passageId\":\"xunzi_ch-15_p-3\",\"order\":3,\"canonicalText\":\"弓矢不調，則羿不能以中微；\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-15_p-3_s-4\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-15\",\"passageId\":\"xunzi_ch-15_p-3\",\"order\":4,\"canonicalText\":\"六馬不和，則造父不能以致遠；\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-15_p-3_s-5\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-15\",\"passageId\":\"xunzi_ch-15_p-3\",\"order\":5,\"canonicalText\":\"士民不親附，則湯武不能以必勝也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-15_p-3_s-6\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-15\",\"passageId\":\"xunzi_ch-15_p-3\",\"order\":6,\"canonicalText\":\"故善附民者，是乃善用兵者也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-15_p-3_s-7\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-15\",\"passageId\":\"xunzi_ch-15_p-3\",\"order\":7,\"canonicalText\":\"故兵要在乎善附民而已。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-15_p-4_s-1\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-15\",\"passageId\":\"xunzi_ch-15_p-4\",\"order\":1,\"canonicalText\":\"臨武君曰：不然。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-15_p-4_s-2\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-15\",\"passageId\":\"xunzi_ch-15_p-4\",\"order\":2,\"canonicalText\":\"兵之所貴者埶利也，所行者變詐也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-15_p-4_s-3\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-15\",\"passageId\":\"xunzi_ch-15_p-4\",\"order\":3,\"canonicalText\":\"善用兵者，感忽悠闇，莫知其所從出。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-15_p-4_s-4\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-15\",\"passageId\":\"xunzi_ch-15_p-4\",\"order\":4,\"canonicalText\":\"孫吳用之無敵於天下，豈必待附民哉！\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-15_p-5_s-1\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-15\",\"passageId\":\"xunzi_ch-15_p-5\",\"order\":1,\"canonicalText\":\"孫卿子曰：不然。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-15_p-5_s-2\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-15\",\"passageId\":\"xunzi_ch-15_p-5\",\"order\":2,\"canonicalText\":\"臣之所道，仁者之兵，王者之志也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-15_p-5_s-3\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-15\",\"passageId\":\"xunzi_ch-15_p-5\",\"order\":3,\"canonicalText\":\"君之所貴，權謀埶利也；\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-15_p-5_s-4\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-15\",\"passageId\":\"xunzi_ch-15_p-5\",\"order\":4,\"canonicalText\":\"所行，攻奪變詐也；\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-15_p-5_s-5\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-15\",\"passageId\":\"xunzi_ch-15_p-5\",\"order\":5,\"canonicalText\":\"諸侯之事也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-15_p-5_s-6\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-15\",\"passageId\":\"xunzi_ch-15_p-5\",\"order\":6,\"canonicalText\":\"仁人之兵，不可詐也；\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-15_p-5_s-7\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-15\",\"passageId\":\"xunzi_ch-15_p-5\",\"order\":7,\"canonicalText\":\"彼可詐者，怠慢者也，路亶者也，君臣上下之間，渙然有離德者也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-15_p-5_s-8\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-15\",\"passageId\":\"xunzi_ch-15_p-5\",\"order\":8,\"canonicalText\":\"故以桀詐桀，猶巧拙有幸焉。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-15_p-5_s-9\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-15\",\"passageId\":\"xunzi_ch-15_p-5\",\"order\":9,\"canonicalText\":\"以桀詐堯，譬之：若以卵投石，以指撓沸；\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-15_p-5_s-10\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-15\",\"passageId\":\"xunzi_ch-15_p-5\",\"order\":10,\"canonicalText\":\"若赴水火，入焉焦沒耳。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-15_p-5_s-11\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-15\",\"passageId\":\"xunzi_ch-15_p-5\",\"order\":11,\"canonicalText\":\"故仁人上下，百將一心，三軍同力；\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-15_p-5_s-12\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-15\",\"passageId\":\"xunzi_ch-15_p-5\",\"order\":12,\"canonicalText\":\"臣之於君也，下之於上也，若子之事父，弟之事兄，若手臂之扞頭目而覆胸腹也，詐而襲之，與先驚而後擊之，一也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-15_p-5_s-13\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-15\",\"passageId\":\"xunzi_ch-15_p-5\",\"order\":13,\"canonicalText\":\"且仁人之用十里之國，則將有百里之聽；\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-15_p-5_s-14\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-15\",\"passageId\":\"xunzi_ch-15_p-5\",\"order\":14,\"canonicalText\":\"用百里之國，則將有千里之聽；\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-15_p-5_s-15\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-15\",\"passageId\":\"xunzi_ch-15_p-5\",\"order\":15,\"canonicalText\":\"用千里之國，則將有四海之聽，必將聰明警戒和傳而一。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-15_p-5_s-16\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-15\",\"passageId\":\"xunzi_ch-15_p-5\",\"order\":16,\"canonicalText\":\"故仁人之兵，聚則成卒，散則成列，延則若莫邪之長刃，嬰之者斷；\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-15_p-5_s-17\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-15\",\"passageId\":\"xunzi_ch-15_p-5\",\"order\":17,\"canonicalText\":\"兌則若莫邪之利鋒，當之者潰，圜居而方止，則若盤石然，觸之者角摧，案角鹿埵隴種東籠而退耳。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-15_p-5_s-18\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-15\",\"passageId\":\"xunzi_ch-15_p-5\",\"order\":18,\"canonicalText\":\"且夫暴國之君，將誰與至哉？\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-15_p-5_s-19\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-15\",\"passageId\":\"xunzi_ch-15_p-5\",\"order\":19,\"canonicalText\":\"彼其所與至者，必其民也，而其民之親我歡若父母，其好我芬若椒蘭，彼反顧其上，則若灼黥，若讎仇；\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-15_p-5_s-20\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-15\",\"passageId\":\"xunzi_ch-15_p-5\",\"order\":20,\"canonicalText\":\"人之情，雖桀蹠，豈又肯為其所惡，賊其所好者哉！\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-15_p-5_s-21\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-15\",\"passageId\":\"xunzi_ch-15_p-5\",\"order\":21,\"canonicalText\":\"是猶使人之子孫自賊其父母也，彼必將來告之，夫又何可詐也！\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-15_p-5_s-22\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-15\",\"passageId\":\"xunzi_ch-15_p-5\",\"order\":22,\"canonicalText\":\"故仁人用國日明，諸侯先順者安，後順者危，慮敵之者削，反之者亡。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-15_p-5_s-23\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-15\",\"passageId\":\"xunzi_ch-15_p-5\",\"order\":23,\"canonicalText\":\"《詩》曰：「武王載發，有虔秉鉞；\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-15_p-5_s-24\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-15\",\"passageId\":\"xunzi_ch-15_p-5\",\"order\":24,\"canonicalText\":\"如火烈烈，則莫我敢遏。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-15_p-5_s-25\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-15\",\"passageId\":\"xunzi_ch-15_p-5\",\"order\":25,\"canonicalText\":\"」此之謂也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-15_p-6_s-1\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-15\",\"passageId\":\"xunzi_ch-15_p-6\",\"order\":1,\"canonicalText\":\"孝成王、臨武君曰：善！\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-15_p-6_s-2\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-15\",\"passageId\":\"xunzi_ch-15_p-6\",\"order\":2,\"canonicalText\":\"請問王者之兵，設何道何行而可？\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-15_p-7_s-1\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-15\",\"passageId\":\"xunzi_ch-15_p-7\",\"order\":1,\"canonicalText\":\"孫卿子曰：凡在大王，將率末事也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-15_p-7_s-2\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-15\",\"passageId\":\"xunzi_ch-15_p-7\",\"order\":2,\"canonicalText\":\"臣請遂道王者諸侯強弱存亡之效，安危之埶：君賢者其國治，君不能者其國亂；\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-15_p-7_s-3\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-15\",\"passageId\":\"xunzi_ch-15_p-7\",\"order\":3,\"canonicalText\":\"隆禮貴義者其國治，簡禮賤義者其國亂；\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-15_p-7_s-4\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-15\",\"passageId\":\"xunzi_ch-15_p-7\",\"order\":4,\"canonicalText\":\"治者強，亂者弱，是強弱之本也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-15_p-7_s-5\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-15\",\"passageId\":\"xunzi_ch-15_p-7\",\"order\":5,\"canonicalText\":\"上足卬則下可用也，上不卬則下不可用也；\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-15_p-7_s-6\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-15\",\"passageId\":\"xunzi_ch-15_p-7\",\"order\":6,\"canonicalText\":\"下可用則強，下不可用則弱，是強弱之常也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-15_p-7_s-7\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-15\",\"passageId\":\"xunzi_ch-15_p-7\",\"order\":7,\"canonicalText\":\"隆禮效功，上也；\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-15_p-7_s-8\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-15\",\"passageId\":\"xunzi_ch-15_p-7\",\"order\":8,\"canonicalText\":\"重祿貴節，次也；\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-15_p-7_s-9\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-15\",\"passageId\":\"xunzi_ch-15_p-7\",\"order\":9,\"canonicalText\":\"上功賤節，下也，是強弱之凡也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-15_p-7_s-10\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-15\",\"passageId\":\"xunzi_ch-15_p-7\",\"order\":10,\"canonicalText\":\"好士者強，不好士者弱；\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-15_p-7_s-11\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-15\",\"passageId\":\"xunzi_ch-15_p-7\",\"order\":11,\"canonicalText\":\"愛民者強，不愛民者弱；\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-15_p-7_s-12\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-15\",\"passageId\":\"xunzi_ch-15_p-7\",\"order\":12,\"canonicalText\":\"政令信者強，政令不信者弱；\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-15_p-7_s-13\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-15\",\"passageId\":\"xunzi_ch-15_p-7\",\"order\":13,\"canonicalText\":\"民齊者強，民不齊者弱；\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-15_p-7_s-14\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-15\",\"passageId\":\"xunzi_ch-15_p-7\",\"order\":14,\"canonicalText\":\"賞重者強，賞輕者弱；\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-15_p-7_s-15\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-15\",\"passageId\":\"xunzi_ch-15_p-7\",\"order\":15,\"canonicalText\":\"刑威者強，刑侮者弱；\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-15_p-7_s-16\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-15\",\"passageId\":\"xunzi_ch-15_p-7\",\"order\":16,\"canonicalText\":\"械用兵革攻完便利者強，械用兵革窳楛不便利者弱。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-15_p-7_s-17\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-15\",\"passageId\":\"xunzi_ch-15_p-7\",\"order\":17,\"canonicalText\":\"重用兵者強，輕用兵者弱；\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-15_p-7_s-18\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-15\",\"passageId\":\"xunzi_ch-15_p-7\",\"order\":18,\"canonicalText\":\"權出一者強，權出二者弱，是強弱之常也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-15_p-8_s-1\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-15\",\"passageId\":\"xunzi_ch-15_p-8\",\"order\":1,\"canonicalText\":\"齊人隆技擊，其技也，得一首者，則賜贖錙金，無本賞矣。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-15_p-8_s-2\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-15\",\"passageId\":\"xunzi_ch-15_p-8\",\"order\":2,\"canonicalText\":\"是事小敵毳，則偷可用也，事大敵堅，則渙然離耳。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-15_p-8_s-3\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-15\",\"passageId\":\"xunzi_ch-15_p-8\",\"order\":3,\"canonicalText\":\"若飛鳥然，傾側反覆無日，是亡國之兵也，兵莫弱是矣。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-15_p-8_s-4\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-15\",\"passageId\":\"xunzi_ch-15_p-8\",\"order\":4,\"canonicalText\":\"是其去賃市傭而戰之幾矣。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-15_p-9_s-1\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-15\",\"passageId\":\"xunzi_ch-15_p-9\",\"order\":1,\"canonicalText\":\"魏氏之武卒，以度取之，衣三屬之甲，操十二石之弩，負服矢五十個，置戈其上，冠冑帶劍，贏三日之糧，日中而趨百里，中試則復其戶，利其田宅，是數年而衰，而未可奪也，改造則不易周也，是故地雖大，其稅必寡，是危國之兵也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-15_p-10_s-1\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-15\",\"passageId\":\"xunzi_ch-15_p-10\",\"order\":1,\"canonicalText\":\"秦人其生民郟阨，其使民也酷烈，劫之以埶，隱之以阨，忸之以慶賞，酋之以刑罰，使天下之民，所以要利於上者，非鬥無由也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-15_p-10_s-2\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-15\",\"passageId\":\"xunzi_ch-15_p-10\",\"order\":2,\"canonicalText\":\"阨而用之，得而後功之，功賞相長也，五甲首而隸五家，是最為眾強長久，多地以正，故四世有勝，非幸也，數也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-15_p-11_s-1\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-15\",\"passageId\":\"xunzi_ch-15_p-11\",\"order\":1,\"canonicalText\":\"故齊之技擊，不可以遇魏氏之武卒；\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-15_p-11_s-2\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-15\",\"passageId\":\"xunzi_ch-15_p-11\",\"order\":2,\"canonicalText\":\"魏氏之武卒，不可以遇秦之銳士；\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-15_p-11_s-3\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-15\",\"passageId\":\"xunzi_ch-15_p-11\",\"order\":3,\"canonicalText\":\"秦之銳士，不可以當桓文之節制；\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-15_p-11_s-4\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-15\",\"passageId\":\"xunzi_ch-15_p-11\",\"order\":4,\"canonicalText\":\"桓文之節制，不可以敵湯武之仁義；\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-15_p-11_s-5\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-15\",\"passageId\":\"xunzi_ch-15_p-11\",\"order\":5,\"canonicalText\":\"有遇之者，若以焦熬投石焉。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-15_p-11_s-6\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-15\",\"passageId\":\"xunzi_ch-15_p-11\",\"order\":6,\"canonicalText\":\"兼是數國者，皆幹賞蹈利之兵也，傭徒鬻賣之道也，未有貴上安制綦節之理也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-15_p-11_s-7\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-15\",\"passageId\":\"xunzi_ch-15_p-11\",\"order\":7,\"canonicalText\":\"諸侯有能微妙之以節，則作而兼殆之耳。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-15_p-11_s-8\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-15\",\"passageId\":\"xunzi_ch-15_p-11\",\"order\":8,\"canonicalText\":\"故招近募選，隆埶詐，尚功利，是漸之也；\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-15_p-11_s-9\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-15\",\"passageId\":\"xunzi_ch-15_p-11\",\"order\":9,\"canonicalText\":\"禮義教化，是齊之也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-15_p-11_s-10\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-15\",\"passageId\":\"xunzi_ch-15_p-11\",\"order\":10,\"canonicalText\":\"故以詐遇詐，猶有巧拙焉；\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-15_p-11_s-11\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-15\",\"passageId\":\"xunzi_ch-15_p-11\",\"order\":11,\"canonicalText\":\"以詐遇齊，闢之猶以錐刀墮太山也，非天下之愚人莫敢試。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-15_p-11_s-12\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-15\",\"passageId\":\"xunzi_ch-15_p-11\",\"order\":12,\"canonicalText\":\"故王者之兵不試。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-15_p-11_s-13\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-15\",\"passageId\":\"xunzi_ch-15_p-11\",\"order\":13,\"canonicalText\":\"湯武之誅桀紂也，拱挹指麾，而強暴之國莫不趨使，誅桀紂若誅獨夫。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-15_p-11_s-14\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-15\",\"passageId\":\"xunzi_ch-15_p-11\",\"order\":14,\"canonicalText\":\"故泰誓曰：「獨夫紂。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-15_p-11_s-15\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-15\",\"passageId\":\"xunzi_ch-15_p-11\",\"order\":15,\"canonicalText\":\"」此之謂也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-15_p-11_s-16\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-15\",\"passageId\":\"xunzi_ch-15_p-11\",\"order\":16,\"canonicalText\":\"故兵大齊則制天下，小齊則治鄰敵。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-15_p-11_s-17\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-15\",\"passageId\":\"xunzi_ch-15_p-11\",\"order\":17,\"canonicalText\":\"若夫招近募選，隆埶詐，尚功利之兵，則勝不勝無常，代翕代張，代存代亡，相為雌雄耳矣。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-15_p-11_s-18\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-15\",\"passageId\":\"xunzi_ch-15_p-11\",\"order\":18,\"canonicalText\":\"夫是之謂盜兵，君子不由也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-15_p-12_s-1\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-15\",\"passageId\":\"xunzi_ch-15_p-12\",\"order\":1,\"canonicalText\":\"故齊之田單，楚之莊蹻，秦之衛鞅，燕之繆蟣，是皆世俗所謂善用兵者也，是其巧拙強弱，則未有以相君也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-15_p-12_s-2\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-15\",\"passageId\":\"xunzi_ch-15_p-12\",\"order\":2,\"canonicalText\":\"若其道一也，未及和齊也；\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-15_p-12_s-3\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-15\",\"passageId\":\"xunzi_ch-15_p-12\",\"order\":3,\"canonicalText\":\"掎契司詐，權謀傾覆，未免盜兵也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-15_p-12_s-4\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-15\",\"passageId\":\"xunzi_ch-15_p-12\",\"order\":4,\"canonicalText\":\"齊桓、晉文、楚莊、吳闔閭、越勾踐是皆和齊之兵也，可謂入其域矣，然而未有本統也，故可以霸而不可以王；\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-15_p-12_s-5\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-15\",\"passageId\":\"xunzi_ch-15_p-12\",\"order\":5,\"canonicalText\":\"是強弱之效也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-15_p-13_s-1\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-15\",\"passageId\":\"xunzi_ch-15_p-13\",\"order\":1,\"canonicalText\":\"孝成王、臨武君曰善！\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-15_p-13_s-2\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-15\",\"passageId\":\"xunzi_ch-15_p-13\",\"order\":2,\"canonicalText\":\"請問為將？\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-15_p-14_s-1\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-15\",\"passageId\":\"xunzi_ch-15_p-14\",\"order\":1,\"canonicalText\":\"孫卿子曰：知莫大乎棄疑，行莫大乎無過，事莫大乎無悔，事至無悔而止矣，成不可必也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-15_p-14_s-2\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-15\",\"passageId\":\"xunzi_ch-15_p-14\",\"order\":2,\"canonicalText\":\"故制號政令欲嚴以威，慶賞刑罰欲必以信，處舍收藏欲周以固，徙舉進退欲安以重，欲疾以速；\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-15_p-14_s-3\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-15\",\"passageId\":\"xunzi_ch-15_p-14\",\"order\":3,\"canonicalText\":\"窺敵觀變欲潛以深，欲伍以參；\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-15_p-14_s-4\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-15\",\"passageId\":\"xunzi_ch-15_p-14\",\"order\":4,\"canonicalText\":\"遇敵決戰必道吾所明，無道吾所疑：夫是之謂六術。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-15_p-14_s-5\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-15\",\"passageId\":\"xunzi_ch-15_p-14\",\"order\":5,\"canonicalText\":\"無欲將而惡廢，無急勝而忘敗，無威內而輕外，無見利而不顧其害，凡慮事欲孰而用財欲泰：夫是之謂五權。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-15_p-14_s-6\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-15\",\"passageId\":\"xunzi_ch-15_p-14\",\"order\":6,\"canonicalText\":\"所以不受命於主有三：可殺而不可使處不完，可殺而不可使擊不勝，可殺而不可使欺百姓：夫是之謂三至。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-15_p-14_s-7\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-15\",\"passageId\":\"xunzi_ch-15_p-14\",\"order\":7,\"canonicalText\":\"凡受命於主而行三軍，三軍既定，百官得序，羣物皆正，則主不能喜，敵不能怒：夫是之謂至臣。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-15_p-14_s-8\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-15\",\"passageId\":\"xunzi_ch-15_p-14\",\"order\":8,\"canonicalText\":\"慮必先事，而申之以敬，慎終如始，終始如一：夫是之謂大吉。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-15_p-14_s-9\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-15\",\"passageId\":\"xunzi_ch-15_p-14\",\"order\":9,\"canonicalText\":\"凡百事之成也，必在敬之；\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-15_p-14_s-10\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-15\",\"passageId\":\"xunzi_ch-15_p-14\",\"order\":10,\"canonicalText\":\"其敗也，必在慢之。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-15_p-14_s-11\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-15\",\"passageId\":\"xunzi_ch-15_p-14\",\"order\":11,\"canonicalText\":\"故敬勝怠則吉，怠勝敬則滅；\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-15_p-14_s-12\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-15\",\"passageId\":\"xunzi_ch-15_p-14\",\"order\":12,\"canonicalText\":\"計勝欲則從，欲勝計則兇。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-15_p-14_s-13\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-15\",\"passageId\":\"xunzi_ch-15_p-14\",\"order\":13,\"canonicalText\":\"戰如守，行如戰，有功如幸，敬謀無壙，敬事無壙，敬吏無壙，敬眾無壙，敬敵無壙：夫是之謂五無壙。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-15_p-14_s-14\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-15\",\"passageId\":\"xunzi_ch-15_p-14\",\"order\":14,\"canonicalText\":\"謹行此六術、五權、三至，而處之以恭敬無壙，夫是之謂天下之將，則通於神明矣。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-15_p-15_s-1\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-15\",\"passageId\":\"xunzi_ch-15_p-15\",\"order\":1,\"canonicalText\":\"臨武君曰：善！\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-15_p-15_s-2\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-15\",\"passageId\":\"xunzi_ch-15_p-15\",\"order\":2,\"canonicalText\":\"請問王者之軍制？\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-15_p-16_s-1\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-15\",\"passageId\":\"xunzi_ch-15_p-16\",\"order\":1,\"canonicalText\":\"孫卿子曰：將死鼓，御死轡，百吏死職，士大夫死行列。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-15_p-16_s-2\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-15\",\"passageId\":\"xunzi_ch-15_p-16\",\"order\":2,\"canonicalText\":\"聞鼓聲而進，聞金聲而退，順命為上，有功次之；\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-15_p-16_s-3\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-15\",\"passageId\":\"xunzi_ch-15_p-16\",\"order\":3,\"canonicalText\":\"令不進而進，猶令不退而退也，其罪惟均。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-15_p-16_s-4\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-15\",\"passageId\":\"xunzi_ch-15_p-16\",\"order\":4,\"canonicalText\":\"不殺老弱，不獵禾稼，服者不禽，格者不捨，奔命者不獲。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-15_p-16_s-5\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-15\",\"passageId\":\"xunzi_ch-15_p-16\",\"order\":5,\"canonicalText\":\"凡誅，非誅其百姓也，誅其亂百姓者也；\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-15_p-16_s-6\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-15\",\"passageId\":\"xunzi_ch-15_p-16\",\"order\":6,\"canonicalText\":\"百姓有扞其賊，則是亦賊也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-15_p-16_s-7\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-15\",\"passageId\":\"xunzi_ch-15_p-16\",\"order\":7,\"canonicalText\":\"以故順刃者生，蘇刃者死，奔命者貢。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-15_p-16_s-8\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-15\",\"passageId\":\"xunzi_ch-15_p-16\",\"order\":8,\"canonicalText\":\"微子開封於宋，曹觸龍斷於軍，殷之服民，所以養生之者也，無異周人。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-15_p-16_s-9\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-15\",\"passageId\":\"xunzi_ch-15_p-16\",\"order\":9,\"canonicalText\":\"故近者歌謳而樂之，遠者竭蹙而趨之，無幽閒闢陋之國，莫不趨使而安樂之，四海之內若一家，通達之屬莫不從服，夫是之謂人師。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-15_p-16_s-10\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-15\",\"passageId\":\"xunzi_ch-15_p-16\",\"order\":10,\"canonicalText\":\"《詩》曰：「自西自東，自南自北，無思不服。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-15_p-16_s-11\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-15\",\"passageId\":\"xunzi_ch-15_p-16\",\"order\":11,\"canonicalText\":\"」此之謂也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-15_p-16_s-12\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-15\",\"passageId\":\"xunzi_ch-15_p-16\",\"order\":12,\"canonicalText\":\"王者有誅而無戰，城守不攻，兵格不擊，上下相喜則慶之，不屠城，不潛軍，不留眾，師不越時。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-15_p-16_s-13\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-15\",\"passageId\":\"xunzi_ch-15_p-16\",\"order\":13,\"canonicalText\":\"故亂者樂其政，不安其上，欲其至也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-15_p-17_s-1\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-15\",\"passageId\":\"xunzi_ch-15_p-17\",\"order\":1,\"canonicalText\":\"臨武君曰：善！\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-15_p-18_s-1\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-15\",\"passageId\":\"xunzi_ch-15_p-18\",\"order\":1,\"canonicalText\":\"陳囂問孫卿子曰：先生議兵，常以仁義為本；\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-15_p-18_s-2\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-15\",\"passageId\":\"xunzi_ch-15_p-18\",\"order\":2,\"canonicalText\":\"仁者愛人，義者循理，然則又何以兵為？\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-15_p-18_s-3\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-15\",\"passageId\":\"xunzi_ch-15_p-18\",\"order\":3,\"canonicalText\":\"凡所為有兵者，為爭奪也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-15_p-19_s-1\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-15\",\"passageId\":\"xunzi_ch-15_p-19\",\"order\":1,\"canonicalText\":\"孫卿子曰：非汝所知也！\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-15_p-19_s-2\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-15\",\"passageId\":\"xunzi_ch-15_p-19\",\"order\":2,\"canonicalText\":\"彼仁者愛人，愛人故惡人之害之也；\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-15_p-19_s-3\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-15\",\"passageId\":\"xunzi_ch-15_p-19\",\"order\":3,\"canonicalText\":\"義者循理，循理故惡人之亂之也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-15_p-19_s-4\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-15\",\"passageId\":\"xunzi_ch-15_p-19\",\"order\":4,\"canonicalText\":\"彼兵者所以禁暴除害也，非爭奪也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-15_p-19_s-5\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-15\",\"passageId\":\"xunzi_ch-15_p-19\",\"order\":5,\"canonicalText\":\"故仁者之兵，所存者神，所過者化，若時雨之降，莫不說喜。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-15_p-19_s-6\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-15\",\"passageId\":\"xunzi_ch-15_p-19\",\"order\":6,\"canonicalText\":\"是以堯伐驩兜，舜伐有苗，禹伐共工，湯伐有夏，文王伐崇，武王伐紂，此四帝兩王，皆以仁義之兵，行於天下也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-15_p-19_s-7\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-15\",\"passageId\":\"xunzi_ch-15_p-19\",\"order\":7,\"canonicalText\":\"故近者親其善，遠方慕其德，兵不血刃，遠邇來服，德盛於此，施及四極。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-15_p-19_s-8\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-15\",\"passageId\":\"xunzi_ch-15_p-19\",\"order\":8,\"canonicalText\":\"《詩》曰：「淑人君子，其儀不忒。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-15_p-19_s-9\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-15\",\"passageId\":\"xunzi_ch-15_p-19\",\"order\":9,\"canonicalText\":\"」此之謂也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-15_p-20_s-1\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-15\",\"passageId\":\"xunzi_ch-15_p-20\",\"order\":1,\"canonicalText\":\"李斯問孫卿子曰：秦四世有勝，兵強海內，威行諸侯，非以仁義為之也，以便從事而已。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-15_p-21_s-1\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-15\",\"passageId\":\"xunzi_ch-15_p-21\",\"order\":1,\"canonicalText\":\"孫卿子曰：非汝所知也！\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-15_p-21_s-2\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-15\",\"passageId\":\"xunzi_ch-15_p-21\",\"order\":2,\"canonicalText\":\"汝所謂便者，不便之便也；\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-15_p-21_s-3\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-15\",\"passageId\":\"xunzi_ch-15_p-21\",\"order\":3,\"canonicalText\":\"吾所謂仁義者，大便之便也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-15_p-21_s-4\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-15\",\"passageId\":\"xunzi_ch-15_p-21\",\"order\":4,\"canonicalText\":\"彼仁義者，所以脩政者也；\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-15_p-21_s-5\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-15\",\"passageId\":\"xunzi_ch-15_p-21\",\"order\":5,\"canonicalText\":\"政脩則民親其上，樂其君，而輕為之死。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-15_p-21_s-6\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-15\",\"passageId\":\"xunzi_ch-15_p-21\",\"order\":6,\"canonicalText\":\"故曰：凡在於軍，將率末事也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-15_p-21_s-7\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-15\",\"passageId\":\"xunzi_ch-15_p-21\",\"order\":7,\"canonicalText\":\"秦四世有勝，諰諰然常恐天下之一合而軋己也，此所謂末世之兵，未有本統也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-15_p-21_s-8\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-15\",\"passageId\":\"xunzi_ch-15_p-21\",\"order\":8,\"canonicalText\":\"故湯之放桀也，非其逐之鳴條之時也；\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-15_p-21_s-9\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-15\",\"passageId\":\"xunzi_ch-15_p-21\",\"order\":9,\"canonicalText\":\"武王之誅紂也，非以甲子之朝而後勝之也，皆前行素脩也，所謂仁義之兵也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-15_p-21_s-10\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-15\",\"passageId\":\"xunzi_ch-15_p-21\",\"order\":10,\"canonicalText\":\"今女不求之於本，而索之於末，此世之所以亂也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-15_p-22_s-1\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-15\",\"passageId\":\"xunzi_ch-15_p-22\",\"order\":1,\"canonicalText\":\"禮者、治辨之極也，強固之本也，威行之道也，功名之總也，王公由之所以得天下也，不由所以隕社稷也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-15_p-22_s-2\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-15\",\"passageId\":\"xunzi_ch-15_p-22\",\"order\":2,\"canonicalText\":\"故堅甲利兵不足以為勝，高城深池不足以為固，嚴令繁刑不足以為威。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-15_p-22_s-3\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-15\",\"passageId\":\"xunzi_ch-15_p-22\",\"order\":3,\"canonicalText\":\"由其道則行，不由其道則廢。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-15_p-23_s-1\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-15\",\"passageId\":\"xunzi_ch-15_p-23\",\"order\":1,\"canonicalText\":\"楚人鮫革犀兕以為甲，鞈堅如金石；\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-15_p-23_s-2\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-15\",\"passageId\":\"xunzi_ch-15_p-23\",\"order\":2,\"canonicalText\":\"宛鉅鐵矛，慘如蜂蠆，輕利僄遫，卒如飄風；\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-15_p-23_s-3\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-15\",\"passageId\":\"xunzi_ch-15_p-23\",\"order\":3,\"canonicalText\":\"然而兵殆於垂沙，唐蔑死。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-15_p-23_s-4\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-15\",\"passageId\":\"xunzi_ch-15_p-23\",\"order\":4,\"canonicalText\":\"莊蹻起，楚分而為三四，是豈無堅甲利兵也哉！\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-15_p-23_s-5\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-15\",\"passageId\":\"xunzi_ch-15_p-23\",\"order\":5,\"canonicalText\":\"其所以統之者非其道故也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-15_p-23_s-6\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-15\",\"passageId\":\"xunzi_ch-15_p-23\",\"order\":6,\"canonicalText\":\"汝潁以為險，江漢以為池，限之以鄧林，緣之以方城；\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-15_p-23_s-7\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-15\",\"passageId\":\"xunzi_ch-15_p-23\",\"order\":7,\"canonicalText\":\"然而秦師至，而鄢郢舉，若振槁然，是豈無固塞隘阻也哉！\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-15_p-23_s-8\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-15\",\"passageId\":\"xunzi_ch-15_p-23\",\"order\":8,\"canonicalText\":\"其所以統之者非其道故也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-15_p-23_s-9\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-15\",\"passageId\":\"xunzi_ch-15_p-23\",\"order\":9,\"canonicalText\":\"紂刳比干，囚箕子，為炮烙刑，殺戮無時，臣下懍然莫必其命，然而周師至，而令不行乎下，不能用其民，是豈令不嚴，刑不繁也哉！\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-15_p-23_s-10\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-15\",\"passageId\":\"xunzi_ch-15_p-23\",\"order\":10,\"canonicalText\":\"其所以統之者非其道故也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-15_p-24_s-1\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-15\",\"passageId\":\"xunzi_ch-15_p-24\",\"order\":1,\"canonicalText\":\"古之兵，戈矛弓矢而已矣，然而敵國不待試而詘；\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-15_p-24_s-2\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-15\",\"passageId\":\"xunzi_ch-15_p-24\",\"order\":2,\"canonicalText\":\"城郭不辨，溝池不抇，固塞不樹，機變不張；\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-15_p-24_s-3\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-15\",\"passageId\":\"xunzi_ch-15_p-24\",\"order\":3,\"canonicalText\":\"然而國晏然不畏外而固者，無它故焉，明道而鈞分之，時使而誠愛之，下之和上也如影嚮，有不由令者，然後俟之以刑。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-15_p-24_s-4\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-15\",\"passageId\":\"xunzi_ch-15_p-24\",\"order\":4,\"canonicalText\":\"故刑一人而天下服，罪人不郵其上，知罪之在己也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-15_p-24_s-5\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-15\",\"passageId\":\"xunzi_ch-15_p-24\",\"order\":5,\"canonicalText\":\"是故刑罰省而威流，無它故焉，由其道故也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-15_p-24_s-6\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-15\",\"passageId\":\"xunzi_ch-15_p-24\",\"order\":6,\"canonicalText\":\"古者帝堯之治天下也，蓋殺一人，刑二人，而天下治。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-15_p-24_s-7\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-15\",\"passageId\":\"xunzi_ch-15_p-24\",\"order\":7,\"canonicalText\":\"傳曰：「威厲而不試，刑錯而不用。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-15_p-24_s-8\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-15\",\"passageId\":\"xunzi_ch-15_p-24\",\"order\":8,\"canonicalText\":\"」此之謂也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-15_p-25_s-1\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-15\",\"passageId\":\"xunzi_ch-15_p-25\",\"order\":1,\"canonicalText\":\"凡人之動也，為賞慶為之，則見害傷焉止矣。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-15_p-25_s-2\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-15\",\"passageId\":\"xunzi_ch-15_p-25\",\"order\":2,\"canonicalText\":\"故賞慶、刑罰、埶詐，不足以盡人之力，致人之死。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-15_p-25_s-3\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-15\",\"passageId\":\"xunzi_ch-15_p-25\",\"order\":3,\"canonicalText\":\"為人主上者也，其所以接下之百姓者，無禮義忠信，焉慮率用賞慶、刑罰、埶詐，除阨其下，獲其功用而已矣。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-15_p-25_s-4\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-15\",\"passageId\":\"xunzi_ch-15_p-25\",\"order\":4,\"canonicalText\":\"大寇則至，使之持危城則必畔，遇敵處戰則必北，勞苦煩辱則必奔，霍焉離耳，下反制其上。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-15_p-25_s-5\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-15\",\"passageId\":\"xunzi_ch-15_p-25\",\"order\":5,\"canonicalText\":\"故賞慶、刑罰、埶詐之為道者，傭徒鬻賣之道也，不足以合大眾，美國家，故古之人羞而不道也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-15_p-25_s-6\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-15\",\"passageId\":\"xunzi_ch-15_p-25\",\"order\":6,\"canonicalText\":\"故厚德音以先之，明禮義以道之，致忠信以愛之，尚賢使能以次之，爵服慶賞以申之，時其事，輕其任，以調齊之，長養之，如保赤子。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-15_p-25_s-7\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-15\",\"passageId\":\"xunzi_ch-15_p-25\",\"order\":7,\"canonicalText\":\"政令以定，風俗以一，有離俗不順其上，則百姓莫不敦惡，莫不毒孽，若祓不祥；\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-15_p-25_s-8\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-15\",\"passageId\":\"xunzi_ch-15_p-25\",\"order\":8,\"canonicalText\":\"然後刑於是起矣。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-15_p-25_s-9\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-15\",\"passageId\":\"xunzi_ch-15_p-25\",\"order\":9,\"canonicalText\":\"是大刑之所加也，辱孰大焉！\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-15_p-25_s-10\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-15\",\"passageId\":\"xunzi_ch-15_p-25\",\"order\":10,\"canonicalText\":\"將以為利邪？\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-15_p-25_s-11\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-15\",\"passageId\":\"xunzi_ch-15_p-25\",\"order\":11,\"canonicalText\":\"則大刑加焉，身苟不狂惑戇陋，誰睹是而不改也哉！\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-15_p-25_s-12\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-15\",\"passageId\":\"xunzi_ch-15_p-25\",\"order\":12,\"canonicalText\":\"然後百姓曉然皆知循上之法，像上之志，而安樂之。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-15_p-25_s-13\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-15\",\"passageId\":\"xunzi_ch-15_p-25\",\"order\":13,\"canonicalText\":\"於是有能化善、脩身、正行、積禮義、尊道德，百姓莫不貴敬，莫不親譽；\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-15_p-25_s-14\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-15\",\"passageId\":\"xunzi_ch-15_p-25\",\"order\":14,\"canonicalText\":\"然後賞於是起矣。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-15_p-25_s-15\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-15\",\"passageId\":\"xunzi_ch-15_p-25\",\"order\":15,\"canonicalText\":\"是高爵豐祿之所加也，榮孰大焉！\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-15_p-25_s-16\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-15\",\"passageId\":\"xunzi_ch-15_p-25\",\"order\":16,\"canonicalText\":\"將以為害邪？\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-15_p-25_s-17\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-15\",\"passageId\":\"xunzi_ch-15_p-25\",\"order\":17,\"canonicalText\":\"則高爵豐祿以持養之；\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-15_p-25_s-18\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-15\",\"passageId\":\"xunzi_ch-15_p-25\",\"order\":18,\"canonicalText\":\"生民之屬，孰不願也！\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-15_p-25_s-19\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-15\",\"passageId\":\"xunzi_ch-15_p-25\",\"order\":19,\"canonicalText\":\"雕雕焉縣貴爵重賞於其前，縣明刑大辱於其後，雖欲無化，能乎哉！\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-15_p-25_s-20\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-15\",\"passageId\":\"xunzi_ch-15_p-25\",\"order\":20,\"canonicalText\":\"故民歸之如流水，所存者神，所為者化，而順，暴悍勇力之屬為之化而願，旁闢曲私之屬為之化而公，矜糾收繚之屬為之化而調，夫是之謂大化至一。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-15_p-25_s-21\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-15\",\"passageId\":\"xunzi_ch-15_p-25\",\"order\":21,\"canonicalText\":\"《詩》曰：「王猶允塞，徐方既來。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-15_p-25_s-22\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-15\",\"passageId\":\"xunzi_ch-15_p-25\",\"order\":22,\"canonicalText\":\"」此之謂也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-15_p-26_s-1\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-15\",\"passageId\":\"xunzi_ch-15_p-26\",\"order\":1,\"canonicalText\":\"凡兼人者有三術：有以德兼人者，有以力兼人者，有以富兼人者。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-15_p-26_s-2\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-15\",\"passageId\":\"xunzi_ch-15_p-26\",\"order\":2,\"canonicalText\":\"彼貴我名聲，美我德行，欲為我民，故闢門除塗，以迎吾入。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-15_p-26_s-3\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-15\",\"passageId\":\"xunzi_ch-15_p-26\",\"order\":3,\"canonicalText\":\"因其民，襲其處，而百姓皆安。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-15_p-26_s-4\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-15\",\"passageId\":\"xunzi_ch-15_p-26\",\"order\":4,\"canonicalText\":\"立法施令，莫不順比。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-15_p-26_s-5\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-15\",\"passageId\":\"xunzi_ch-15_p-26\",\"order\":5,\"canonicalText\":\"是故得地而權彌重，兼人而兵俞強：是以德兼人者也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-15_p-26_s-6\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-15\",\"passageId\":\"xunzi_ch-15_p-26\",\"order\":6,\"canonicalText\":\"非貴我名聲也，非美我德行也，彼畏我威，劫我埶，故民雖有離心，不敢有畔慮，若是則戎甲俞眾，奉養必費。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-15_p-26_s-7\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-15\",\"passageId\":\"xunzi_ch-15_p-26\",\"order\":7,\"canonicalText\":\"是故得地而權彌輕，兼人而兵俞弱：是以力兼人者也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-15_p-26_s-8\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-15\",\"passageId\":\"xunzi_ch-15_p-26\",\"order\":8,\"canonicalText\":\"非貴我名聲也，非美我德行也，用貧求富，用飢求飽，虛腹張口，來歸我食。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-15_p-26_s-9\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-15\",\"passageId\":\"xunzi_ch-15_p-26\",\"order\":9,\"canonicalText\":\"若是，則必發夫掌窌之粟以食之，委之財貨以富之，立良有司以接之，已期三年，然後民可信也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-15_p-26_s-10\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-15\",\"passageId\":\"xunzi_ch-15_p-26\",\"order\":10,\"canonicalText\":\"是故得地而權彌輕，兼人而國俞貧：是以富兼人者也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-15_p-26_s-11\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-15\",\"passageId\":\"xunzi_ch-15_p-26\",\"order\":11,\"canonicalText\":\"故曰：以德兼人者王，以力兼人者弱，以富兼人者貧，古今一也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-15_p-27_s-1\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-15\",\"passageId\":\"xunzi_ch-15_p-27\",\"order\":1,\"canonicalText\":\"兼併易能也，唯堅凝之難焉。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-15_p-27_s-2\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-15\",\"passageId\":\"xunzi_ch-15_p-27\",\"order\":2,\"canonicalText\":\"齊能並宋，而不能凝也，故魏奪之。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-15_p-27_s-3\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-15\",\"passageId\":\"xunzi_ch-15_p-27\",\"order\":3,\"canonicalText\":\"燕能並齊，而不能凝也，故田單奪之。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-15_p-27_s-4\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-15\",\"passageId\":\"xunzi_ch-15_p-27\",\"order\":4,\"canonicalText\":\"韓之上地，方數百里，完全富足而趨趙，趙不能凝也，故秦奪之。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-15_p-27_s-5\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-15\",\"passageId\":\"xunzi_ch-15_p-27\",\"order\":5,\"canonicalText\":\"故能並之，而不能凝，則必奪；\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-15_p-27_s-6\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-15\",\"passageId\":\"xunzi_ch-15_p-27\",\"order\":6,\"canonicalText\":\"不能並之，又不能凝其有，則必亡。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-15_p-27_s-7\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-15\",\"passageId\":\"xunzi_ch-15_p-27\",\"order\":7,\"canonicalText\":\"能凝之，則必能並之矣。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-15_p-27_s-8\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-15\",\"passageId\":\"xunzi_ch-15_p-27\",\"order\":8,\"canonicalText\":\"得之則凝，兼併無強。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-15_p-27_s-9\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-15\",\"passageId\":\"xunzi_ch-15_p-27\",\"order\":9,\"canonicalText\":\"古者湯以薄，武王以滈，皆百里之地也，天下為一，諸侯為臣，無他故焉，能凝之也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-15_p-27_s-10\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-15\",\"passageId\":\"xunzi_ch-15_p-27\",\"order\":10,\"canonicalText\":\"故凝士以禮，凝民以政；\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-15_p-27_s-11\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-15\",\"passageId\":\"xunzi_ch-15_p-27\",\"order\":11,\"canonicalText\":\"禮脩而士服，政平而民安；\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-15_p-27_s-12\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-15\",\"passageId\":\"xunzi_ch-15_p-27\",\"order\":12,\"canonicalText\":\"士服民安，夫是之謂大凝。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-15_p-27_s-13\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-15\",\"passageId\":\"xunzi_ch-15_p-27\",\"order\":13,\"canonicalText\":\"以守則固，以徵則強，令行禁止，王者之事畢矣。\",\"chunks\":[],\"tags\":[]}]}") as ChapterBundle
